const e=[{id:1,code:"GOV-101",icon:"DoorOpen",accent:"#2563eb",title:"پلانا دەرکەفتنا تەنگاڤیێ",subtitle:"Emergency Evacuation Plans",summary:"چێکرنا پلانا دەرکەفتنێ بۆ فەرمانگەه و ئاڤاهیێن حکومی",blocks:[{body:"پلانا دەرکەفتنا تەنگاڤیێ ئێک ژ گرنگترین بەلگەنامەیێن هەر فەرمانگەهەکا حکومی یە. ئەڤ پلانە ژیانا فەرمانبەر و سەرەدانکەران دپارێزیت ل دەمێ ڕویدانێن وەکی ئاگرکەفتن، عەردەهەژین یان مەترسیێن کیمیایی."},{heading:"١. هەنگاڤێن چێکرنا پلانێ",body:"پلانەکا سەرکەفتی پێدڤی ب ڤان هەنگاڤان هەیە:",points:["نەخشە: نەخشەیەکا تەمام یا ئاڤاهیێ ب ڕێکێن دەرکەفتنێ و جهێن تەمرینکان ڤە چێبکە","ڕێکێن دەرکەفتنێ: هەر قاتەک لایێ کێم دوو ڕێکێن دەرکەفتنێ یێن ژێک دویر هەبن (NFPA 101)، و دەرگەهێن دەرکەفتنێ دڤێت ژ ناڤدا بێ کلیل ڤەببن","خالا کۆمبوونێ: جهەکێ سەلامەت ل دەرڤەی ئاڤاهیێ، ب دویراتیا پێشنیارکری لایێ کێم ٥٠ مەتر","بەرپرسیاری: بۆ هەر قاتەکی بەرپرسەکێ دەرکەفتنێ دیار بکە","سیستەمێ ئاگەهدارکرنێ: زەنگ یان سیرێنا ئاگری کو ل هەمی قاتان بهێتە بهیستن","ڕاهێنان: هەر ٣ هەیڤان جارەکێ ڕاهێنانا پراکتیکی یا دەرکەفتنێ"]},{heading:"٢. ڕێسایێن دەرکەفتنا سەلامەت",body:"دەمێ زەنگا ئاگەهدارکرنێ لێدا:",points:["ب ئارامی و ب ڕێکوپێکی بچە — نەڕەڤە","ئەسانسۆرێ بکارنەئینە — تەنێ ب پلەکانان دەرکەڤە","ئەگەر دوکێل هەبوو، خوە نزم بکە و ل بن دوکێلێ ب چۆکان بچە","بەری ڤەکرنێ، ب پشتا دەستی دەرگەهی بپشکنە — ئەگەر گەرم بوو ڤەنەکە و ڕێکەکا دی ببینە","هاریکاریا کەسێن پێدڤی ب هاریکاریێ بکە و دەرگەهان ل پشت خوە بگرە","ڕاستەوخوە بچە خالا کۆمبوونێ و ل وێرێ بمینە"]},{heading:"٣. ڕۆلا بەرپرسان",body:"هەر قاتەک پێدڤی ب بەرپرسەکێ ئاگری هەیە:",points:["بەرپرسێ ئاگری (Fire Warden): بەرپرسێ سەرەکی یێ قاتی","پشکنینا هەمی ژووران (تووالێت و کۆگەهـ ژی) دا کەس نەمینیت","ڕێنیشاندانا کەسان بۆ ڕێکێن دەرکەفتنێ","ژمارتنا کەسان ل خالا کۆمبوونێ و ئاگەهدارکرنا تیمێ ١١٥"]}],media:[{kind:"image",src:"media/images/gov_evacuation.png",title:"نەخشەیا دەرکەفتنێ",description:"نموونەیا نەخشەیەکێ"}],quiz:[{question:"پێشنیار دهێتە کرن کو خالا کۆمبوونێ چەند ژ ئاڤاهیێ دویر بیت؟",options:[{text:"١٠ مەتر",correct:!1},{text:"٢٥ مەتر",correct:!1},{text:"٥٠ مەتر",correct:!0},{text:"١٠٠ مەتر",correct:!1}],explanation:"لایێ کێم ٥٠ مەتر، دا ژ کەفتنا شیشە و پارچەیان و ژ دوکێلێ دویر بیت و ڕێکا ترومبێلێن تەنگاڤیێ نەگریت."}]},{id:2,code:"GOV-102",icon:"FileLock",accent:"#059669",title:"پاراستنا بەلگەنامەیان",subtitle:"Document Protection",summary:"ڕێکارێن پاراستنا بەلگەنامەیێن گرنگ ژ ئاگر و ئاڤێ",blocks:[{body:"بەلگەنامەیێن حکومی سامانەکێ گرانبهانە. وندابوونا وان ب ئاگری یان ب ئاڤێ دشێت کارێ فەرمانگەهێ ڕاوەستینیت و مافێن خەلکی ژناڤ ببەت. ژبەر هندێ پاراستن و کۆپیکرنا وان پێدڤییە."},{heading:"١. پۆلینکرنا بەلگەنامەیان",body:"دیارکرنا گرنگیا بەلگەنامەیان:",points:["ئاستێ A — گەلەک گرنگ: گرێبەست، دارایی، یاسایی","ئاستێ B — گرنگ: ڕاپۆرت و نامەیێن فەرمی","ئاستێ C — ئاسایی: نامەیێن نەفەرمی"]},{heading:"٢. پاراستنا فیزیکی",body:"ڕێکارێن پاراستنا فیزیکی:",points:["سەیفێن بەرگەگرێن ئاگری: بۆ بەلگەنامەیێن ئاستێ A","دۆلابێن کانزایی یێن قفلکری، بلندتر ژ ئەردی","کیس و سندوقێن پلاستیکی یێن دژی ئاڤێ","کۆنترۆلکرنا ژینگەهێ: جهەکێ فێنک و هشک ب گەرمی و شێداریەکا جیگیر"]},{heading:"٣. ڕێسایا ٣-٢-١ بۆ کۆپیێن پاشکەفتی (Backup)",body:"ڕێسایا ٣-٢-١:",points:["٣ کۆپی ژ هەر داتایەکا گرنگ","٢ جۆرێن جودا یێن هەلگرتنێ (مێدیا)","١ کۆپی ل جهەکێ دی، ل دەرڤەی ئاڤاهیێ"]}],media:[{kind:"image",src:"media/images/gov_backup.png",title:"کۆپیێن پاشکەفتی (Backup)",description:"ڕێسایا ٣-٢-١"}],quiz:[{question:"ڕێسایا ٣-٢-١ چ دگەهینیت؟",options:[{text:"٣ کۆمپیوتەر",correct:!1},{text:"٣ کۆپی، ٢ جۆرێن مێدیا، ١ ل دەرڤە",correct:!0},{text:"٣ ڕۆژ",correct:!1},{text:"٣ فەرمانبەر",correct:!1}],explanation:"٣ کۆپی ل سەر ٢ جۆرێن مێدیا، و ١ کۆپی ل جهەکێ دی ل دەرڤەی ئاڤاهیێ."}]},{id:3,code:"GOV-103",icon:"Zap",accent:"#ca8a04",title:"سەلامەتیا کارەبایێ",subtitle:"Electrical Safety",summary:"مەترسیێن کارەبایێ ل فەرمانگەهان و پشکنینا ئامێران",blocks:[{body:"کارەبا ئێک ژ ئەگەرێن سەرەکی یێن ئاگرکەفتنێ یە ل فەرمانگەهان. وایەرێن کەڤن، زێدەبارکرنا پلاکان و ئامێرێن گەرمکرنێ دڤێت ب ڕێکوپێکی بهێنە پشکنین."},{heading:"١. مەترسیێن کارەبایێ",body:"مەترسیێن بەلاڤ ل فەرمانگەهان:",points:["زێدەبارکرن: گەلەک ئامێر ل سەر ئێک پلاکێ","وایەرێن کەڤن یێن پۆست قەلشی یان شکەستی","ئاڤ نێزیکی ئامێر و پلاکێن کارەبایێ","وایەرێن درێژکەر (Extension): بکارئینانا وان یا گەلەک و هەمیشەیی"]},{heading:"٢. ڕێسایێن سەلامەتیێ",body:"ڕێسایێن ڕۆژانە:",points:["وایەرێ درێژکەر ب وایەرەکێ درێژکەرێ دی ڤە گرێ نەدە","بەری دەستدانا پلاکێ، دەستێن تە دڤێت هشک بن","گەرمکەری ڕاستەوخوە ب پلاکا دیواری ڤە گرێبدە، نە ب وایەرێ درێژکەر"]},{heading:"٣. ئاگرێ کارەبایێ",body:"ئەگەر ئاگر ل ئامێرەکێ کارەبایێ کەفت:",points:["ئەگەر ب سەلامەتی دکاری، کارەبایێ ژ تابلۆیێ ببڕە و گازی ١١٥ بکە","ئەگەر ئاگر بچووک بیت و تو ڕاهێنان دیتی بی، تەمرینکا CO₂ یان تۆزا هشک (ABC) بکاربینە و ڕێکا دەرکەفتنێ ل پشت تە بیت؛ ئەگەر نە، دەرکەڤە","ئاڤ و کەف نە، ئەگەر ل سەر لایبلێ پۆلا C یان نیشانا تاقیکرنا کارەبایێ نەبیت — مەترسیا شۆکا کارەبایێ هەیە"]}],media:[{kind:"video",src:"media/videos/gov_electrical.mp4",title:"سەلامەتیا کارەبایێ",description:"ڕێنمایی"}],quiz:[{question:"کیژ تەمرینک باشترە بۆ ئاگرێ کارەبایێ؟",options:[{text:"ئاڤ",correct:!1},{text:"کەف",correct:!1},{text:"CO₂ یان تۆزا هشک",correct:!0},{text:"بەتانی",correct:!1}],explanation:"CO₂ و تۆزا هشک کارەبایێ ناگوهێزن؛ ئاڤ و کەفا ئاسایی کارەبایێ دگوهێزن و دشێن شۆکێ چێبکەن."}]},{id:4,code:"GOV-104",icon:"HeartPulse",accent:"#dc2626",title:"بەرنامەیێ هەوارهاتنا ئێکێ",subtitle:"First Aid Program",summary:"چێکرنا تیمێ هەوارهاتنا ئێکێ و ئامادەکرنا کەرەستەیان",blocks:[{body:"هەر فەرمانگەهەک پێدڤی ب بەرنامەیەکێ هەوارهاتنا ئێکێ هەیە. پێشنیار دهێتە کرن کو ل هەر قاتەکی و ل هەر دەوامەکێ لایێ کێم ئێک کەسێ ڕاهێنانکری هەبیت، و ل فەرمانگەهێن مەزن پتر."},{heading:"١. تیمێ هەوارهاتنا ئێکێ",body:"پێکهاتا تیمی:",points:["لایێ کێم ئێک کەسێ ڕاهێنانکری ل هەر قاتەکی و ل هەر دەوامەکێ","کۆرسەکێ پەسەندکری یێ هەوارهاتنا ئێکێ، فشارا سنگی (CPR) و AED","نووکرنا ڕاهێنانێ و بەلگەنامەیێ هەر ٢ سالان"]},{heading:"٢. سندوقێ هەوارهاتنا ئێکێ",body:"کەرەستەیێن پێدڤی:",points:["پەتی (Bandage) و گازێ پاقژ (Gauze)","ماددێن پاقژکرنا برینێ (Antiseptic)","مقەس و پەنس","دەستکێشێن پزیشکی یێن ئێکجاری","ماسکا CPR بۆ دانا هەناسێ ب سەلامەتی"]},{heading:"٣. فشارا سنگی (CPR)",body:"هەنگاڤێن CPR بۆ مەزنان:",points:["١. ئەگەر کەس بەرسڤێ نادەت و ب دروستی هەناسێ نادەت: گازی ١٢٢ بکە و AED داخواز بکە؛ ل سەر پشتێ ل سەر ئەردەکێ ڕەق دانە","٢. ٣٠ فشارێن سنگی ل ناڤەراستا سنگی: کویراهی ٥-٦ سم، لەز ١٠٠-١٢٠ فشار د خولەکێ دا","٣. ٢ هەناسە (هەر ئێک نێزیکی ١ چرکە) ئەگەر تو ڕاهێنانکری بی؛ ئەگەر نە، تەنێ فشارێن سنگی بکە","٤. ب ڕێژا ٣٠:٢ بەردەوام بە هەتا AED یان ئەمبوولانس دگەهیت؛ AED ئێکسەر بکاربینە"]}],media:[{kind:"video",src:"media/videos/gov_cpr.mp4",title:"فشارا سنگی (CPR)",description:"چەوانیا کرنا CPR"}],quiz:[{question:"د CPR دا، بەری ٢ هەناسان چەند فشارێن سنگی دهێنە کرن؟",options:[{text:"١٠",correct:!1},{text:"١٥",correct:!1},{text:"٣٠",correct:!0},{text:"٥٠",correct:!1}],explanation:"ڕێژا دروست بۆ مەزنان ٣٠:٢ یە (AHA 2025)."}]},{id:5,code:"GOV-105",icon:"Flame",accent:"#ea580c",title:"ئاگر و تەمرینک ل فەرمانگەهان",subtitle:"Fire Prevention & Extinguisher Use",summary:"ڕێگرتن ل ئاگرکەفتنێ و بکارئینانا تەمرینکان ل ئاڤاهیێن حکومی",blocks:[{body:"ئاگرکەفتن ل فەرمانگەهان مەترسیەکا جددی یە. کاغەز، کۆمپیوتەر، وایەرێن کەڤن و زێدەبارکرنا کارەبایێ ئەگەرێن سەرەکی یێن ئاگری نە. بەرنامەیەکێ ڕێگرتن و ئامادەکاریێ ژیانا فەرمانبەران و سامانێ گشتی دپارێزیت."},{heading:"١. ئەگەرێن ئاگری ل فەرمانگەهان",body:"ئەگەرێن سەرەکی:",points:["زێدەبارکرنا کارەبایێ: گەلەک ئامێر ل سەر ئێک پلاکێ","کاغەز و بەلگەنامە: ماددێن ب ساناهی دسوژن","جگارە و شخاتە: ئەگەرەکێ سەرەکی یێ هەلبوونا ئاگری","سۆبە و گەرمکەرێن گوهێزبار: مەترسیا زڤستانێ","مەتبەخێن بچووک: ل دەمێ چێکرنا چا و قەهوێ","باتری و شەحنکەر: گەرمبوونا زێدە"]},{heading:"٢. جۆرێن تەمرینکان",body:"بۆ فەرمانگەهان ئەڤ جۆرە پێدڤینە:",points:["تەمرینکا تۆزا هشک (ABC): بۆ ئاگرێن پۆلێن A، B و C — نە بۆ کانزایان (D) و نە بۆ ڕۆنێ مەتبەخێ (K)","تەمرینکا CO₂: بۆ ئاگرێ ئامێرێن کارەبایێ — زیانێ ناگەهینیتە کۆمپیوتەران","تەمرینکا ئاڤێ: تەنێ بۆ پۆلا A (کاغەز، دار، جل) — نە بۆ کارەبایێ و ڕۆنی","کۆدا بەریتانی BS 5306-8 پێشنیار دکەت کو لایێ کێم ٢ تەمرینک ل هەر قاتەکی هەبن (ژبلی قاتێن گەلەک بچووک)؛ یاسایا فەرمانگەهێن دهۆکێ ژ لایێ ڕێڤەبەرییا بەرگرییا شارستانی ڤە دهێتە دانان و هێشتا نەهاتییە پشتڕاستکرن","تەمرینکان نێزیکی دەرگەهان و ل سەر ڕێکێن دەرکەفتنێ دابنێ","پشکنینا ب چاڤ یا هەیڤانە (مێخا سەلامەتیێ و مۆر نەشکەستی بن، لایبل بهێتە خوەندن، ئەگەر دەرزیا فشارێ هەبیت ل ناڤچەیا کەسک بیت؛ تەمرینکێن CO₂ دەرزیا فشارێ نینە، لەوا ڕاکە دا هەست بکەی کو تژی یە) و پشکنین و چاککرنا سالانە ژ لایێ کەسەکێ شارەزا ڤە (NFPA 10)"]},{heading:"٣. ڕێکارا PASS",body:`بەری تو تەمرینکێ بکار بینی (دڤێت هەمی بەرسڤ «بەلێ» بن):
• ئاگر بچووکە و تازە دەستپێکرییە، وەک ئاگرەکێ د سەتلەکا زبلی یان تاوەیەکێ دا.
• تەمرینک یا گونجایە بۆ ڤی جۆرێ ئاگری.
• ڕێکا دەرکەفتنێ ل پشت تەیە و ئاگر د ناڤبەرا تە و دەرکەفتنێ دا نینە.
• ئاگەهداری هاتییە دان: کەسێن دی ئاگەهدار بوون و گازی ١١٥ هاتییە کرن.
• تو بۆ بکارئینانا تەمرینکێ ڕاهێنان دیتی یی.
• چو دوکێل یان گەرمی ڕێکا دەرکەفتنا تە ناگریت.
• ئەگەر ئاگر ئێکسەر ڤەنەمری، ڕاوەستە، دەرکەڤە و دەرگەهی ل پشت خوە بگرە.

ڕێکارا PASS ڕێکارا گشتی یە بۆ پترییا تەمرینکێن دەستی. تەمرینکێن Class D، ماددێ تەڕ (Wet Chemical)، ماددێن پاقژ (Clean Agent) و یێن ل سەر چەرخان: ل دویڤ لایبلێ و ڕێنمایێن کۆمپانیا دروستکەر بکار بینە. چەوانیا بکارئینانا تەمرینکێ:`,points:["P = Pull (بکێشە): مێخا سەلامەتیێ بکێشە و دەربێخە","A = Aim (ئاراستە بکە): سەرێ لوولەیێ (Nozzle) ئاراستەی بنێ ئاگری بکە","S = Squeeze (بگڤاشە): دەسکێ تەمرینکێ ب هێز بگڤاشە","S = Sweep (بلڤینە): ل بنێ ئاگری ژ لایەکی بۆ لایێ دی بلڤینە","دویراتی: ژ وێ دویراتیێ دەستپێبکە یا ل سەر لایبلێ تەمرینکێ یان د ڕێنمایێن کۆمپانیا دروستکەر دا هاتی، ڕێکا دەرکەفتنێ ل پشت تە بیت، و تەنێ دەمێ ئاگر بچووک دبیت نێزیکتر ببە","ڕێکا دەرکەفتنێ ل پشت خوە بهێلە؛ ئەگەر ئاگر ئێکسەر ڤەنەمری یان دەست ب بەلاڤبوونێ کر، دەرکەڤە، دەرگەهی ل پشت خوە بگرە و پشتڕاست ببە کو گازی ١١٥ هاتییە کرن"]},{heading:"٤. سیستەمێن ئاگەهدارکرنێ",body:"سیستەمێن پێدڤی ل فەرمانگەهان:",points:["سیرێنا ئاگری: دڤێت ل هەر قاتەکی بهێتە بهیستن","دوگمەیا ئاگەهدارکرنێ (Pull Station): نێزیکی دەرکەفتنان","ناسینا دوکێلێ (Smoke Detection): وەک کۆدا ئاگری یا ئاڤاهی (Fire Code) دخوازیت (پێدڤیاتیا فەرمانگەهێن دهۆکێ هێشتا نەهاتییە پشتڕاستکرن)","ڕۆناهیا تەنگاڤیێ: ب خوە هەلدبیت دەمێ کارەبا دچیت","ژمارا ١١٥ ل سەر دیوارێ هەر ژوورەکێ بنڤیسە"]}],media:[{kind:"video",src:"media/videos/gov_fire_prevention.mp4",title:"ڕێگرتن ل ئاگری",description:"ڕێنماییێن تەمام بۆ فەرمانگەهان"},{kind:"image",src:"media/images/gov_pass_method.png",title:"ڕێکارا PASS",description:"هەنگاڤ ب هەنگاڤ"},{kind:"image",src:"media/images/gov_extinguisher_types.png",title:"جۆرێن تەمرینکان",description:"ABC، CO₂، ئاڤ"}],quiz:[{question:"کیژ تەمرینک باشترە بۆ ئاگرێ کۆمپیوتەران؟",options:[{text:"تەمرینکا ئاڤێ",correct:!1},{text:"تەمرینکا CO₂",correct:!0},{text:"تەمرینکا کەفێ",correct:!1},{text:"بەتانی",correct:!1}],explanation:"CO₂ زیانێ ناگەهینیتە کۆمپیوتەران و کارەبایێ ناگوهێزیت."},{question:"د ڕێکارا PASS دا، A چ دگەهینیت؟",options:[{text:"Alert (ئاگەهداری)",correct:!1},{text:"Aim (ئاراستە بکە)",correct:!0},{text:"Action (کار)",correct:!1},{text:"Away (دویر)",correct:!1}],explanation:"A = Aim: سەرێ لوولەیێ ئاراستەی بنێ ئاگری بکە."},{question:"کۆدا بەریتانی BS 5306-8 لایێ کێم چەند تەمرینکان ل هەر قاتەکی پێشنیار دکەت؟",options:[{text:"١ تەمرینک",correct:!1},{text:"٢ تەمرینک",correct:!0},{text:"٣ تەمرینک",correct:!1},{text:"٥ تەمرینک",correct:!1}],explanation:"کۆدا بەریتانی BS 5306-8 پێشنیار دکەت کو لایێ کێم ٢ تەمرینک ل هەر قاتەکی هەبن (ژبلی قاتێن گەلەک بچووک)، و دڤێت دویراتیا گەهشتنا وان ژی ژ سنووری دەرنەکەڤیت. یاسایا فەرمانگەهێن دهۆکێ ژ لایێ ڕێڤەبەرییا بەرگرییا شارستانی ڤە دهێتە دانان و هێشتا نەهاتییە پشتڕاستکرن."}]},{id:6,code:"GOV-106",icon:"Activity",accent:"#d97706",title:"عەردەهەژین ل ئاڤاهیێن حکومی",subtitle:"Earthquake Safety in Gov Buildings",summary:"چەوانیا خوە پاراستنێ و دەرکەفتنا سەلامەت ل دەمێ عەردەهەژینێ",blocks:[{body:"هەرێما کوردستانێ ل سەر ناڤچەیەکا چالاکا عەردەهەژینێ یە. ئاڤاهیێن حکومی، ب تایبەتی یێن کەڤن، مەترسیدارن. ئامادەبوون و زانینا ڕێکاران ژیانێ ڕزگار دکەت."},{heading:"١. ل دەمێ عەردەهەژینێ",body:"ئەگەر تو ل ناڤ فەرمانگەهێ بووی:",points:["بکەڤە (Drop): ئێکسەر ل سەر چۆک و دەستان بکەڤە","خوە بپارێزە (Cover): بچە بن مێزەکا قایم، دویر ژ پەنجەرە و دۆلابێن گران (نە ل بەر دەرگەهی)، و سەر و ستۆیێ خوە بپارێزە","بگرە (Hold On): پێیا مێزێ بگرە هەتا هەژین ڕادوەستیت","بەرەڤ دەرڤە نەڕەڤە — گەلەک برینداربوون ل دەمێ ڕەڤینێ و ژ کەفتنا پارچەیان چێدبن","ئەسانسۆرێ بکارنەئینە — دبیت ڕاوەستیت و تو تێدا بمینی","ئەگەر تو ل جهەکێ ڤەکری بووی: دویر ژ ئاڤاهیان، تێلێن کارەبایێ و ستوینان بە"]},{heading:"٢. پشتی عەردەهەژینێ",body:"هەنگاڤێن پشتی عەردەهەژینێ:",points:["خوە و هەڤکارێن خوە بۆ برینداربوونێ بپشکنە","ب پلەکانان دەرکەڤە (ئەسانسۆر نە!)","ئەگەر بێهنا غازێ هات یان دەنگێ دەرکەفتنا غازێ گوهـ لێبوو: دەرکەڤە و ژ دەرڤە گازی ١١٥ بکە؛ تەنێ کارمەندێن ڕاهێنای و دەستنیشانکری غازێ ژ کێلۆنا سەرەکی دبڕن، ئەگەر گەهشتن بۆ وێ سەلامەت بیت، بێ چوونا د وی جهی دا یێ غاز لێ کۆم بوویە و بێ دەستدانا چ سویچان","بچە خالا کۆمبوونێ و کەسان بژمێرە","ئەگەر بریندار یان کەسێن د بن کەلاوەیان دا مای هەبن، گازی ١١٥ و ١٢٢ بکە","ئاگەهداری هەژینێن پاشی (Aftershocks) بە","نەزڤڕە ناڤ ئاڤاهیێ هەتا شارەزا سەلامەتیا وێ پشتڕاست نەکەن"]},{heading:"٣. ئامادەکاریا پێشوەخت",body:"ئامادەکاریێن پێدڤی:",points:["پلانا عەردەهەژینێ چێبکە و ل سەر دیواری هەلاویسە","دۆلاب، ڕەفک و ئامێرێن گران ب دیواری ڤە قایم بکە","جانتایا تەنگاڤیێ ل هەر قاتەکی ئامادە بکە","پشکنینا ئاڤاهیێ ژ لایێ ئەندازیارەکێ شارەزا ڤە هەر سال","ڕاهێنانا Drop, Cover, Hold On هەر ٣ هەیڤان","دوو خالێن کۆمبوونێ دیار بکە (ئێک نێزیک و ئێک دویر)"]},{heading:"٤. بەرپرسیاریا ڕێڤەبەران",body:"ڕێڤەبەر دڤێت:",points:["بۆ هەر قاتەکی بەرپرسەکێ عەردەهەژینێ دیار بکەن","لیستا فەرمانبەران بۆ ژمارتنا کەسان ئامادە بهێلن","پلانەکا تایبەت بۆ کەسێن خودان پێدڤیێن تایبەت دابنێن","سیستەمێ ئاگەهدارکرنێ ب ڕێکوپێکی بپشکنن","ژمارێن تەنگاڤیێ (١١٥، ١٢٢، ١٠٤) ل هەر ژوورەکێ بنڤیسن"]}],media:[{kind:"video",src:"media/videos/gov_earthquake.mp4",title:"عەردەهەژین ل فەرمانگەهێ",description:"ڕاهێنانا پراکتیکی"},{kind:"image",src:"media/images/gov_drop_cover_hold.png",title:"بکەڤە، خوە بپارێزە، بگرە (Drop, Cover, Hold On)",description:"هەنگاڤ ب هەنگاڤ"}],quiz:[{question:"ل دەمێ عەردەهەژینێ، ئێکەم کار چییە؟",options:[{text:"بەرەڤ دەرڤە بڕەڤە",correct:!1},{text:"بچە ناڤ ئەسانسۆرێ",correct:!1},{text:"Drop, Cover, Hold On",correct:!0},{text:"پەنجەرەیان ڤەکە",correct:!1}],explanation:"ل بن مێزەکا قایم بکەڤە، خوە بپارێزە و بگرە هەتا هەژین ڕادوەستیت."},{question:"پشتی عەردەهەژینێ، بۆ دەرکەفتنێ ژ ئاڤاهیێ چ بکاردئینین؟",options:[{text:"ئەسانسۆر",correct:!1},{text:"پلەکانێن ئاڤاهیێ",correct:!0},{text:"پەنجەرە",correct:!1},{text:"چ جوداهی نینە",correct:!1}],explanation:"هەمیشە ب پلەکانان دەرکەڤە — ئەسانسۆر دبیت ڕاوەستیت."},{question:"ل دویڤ ڤێ بەرنامەیێ، ڕاهێنانا عەردەهەژینێ ل فەرمانگەهێ هەر چەند جاران پێدڤییە؟",options:[{text:"هەر سالەکێ",correct:!1},{text:"هەر ٦ هەیڤان",correct:!1},{text:"هەر ٣ هەیڤان",correct:!0},{text:"تەنێ ئێک جار",correct:!1}],explanation:"ئەڤ بەرنامە پێشنیار دکەت هەر ٣ هەیڤان جارەکێ ڕاهێنانا پراکتیکی بهێتە کرن."}]},{id:7,code:"GOV-107",icon:"Wind",accent:"#475569",title:"سەلامەتیا غازێ و هەواگوهۆڕین",subtitle:"Gas Safety & Ventilation",summary:"مەترسیێن غازێ ل فەرمانگەهان و گرنگیا هەواگوهۆڕینا دروست",blocks:[{body:"ل زڤستانێ سۆبە و گەرمکەرێن غاز و نەفتێ ل فەرمانگەهان گەلەک دهێنە بکارئینان. دەرکەفتنا غازێ دشێت ببیتە ئەگەرێ تەقین و ئاگری، و سووتنا نە تەمام غازا ژەهراوی یا مۆنۆکسیدا کاربۆنێ (CO) چێدکەت کو بێ ڕەنگ و بێ بێهنە و دشێت بکوژیت. هەواگوهۆڕینا دروست و ناسینا مەترسیان ژیانێ ڕزگار دکەت."},{heading:"١. مەترسیا غازا مۆنۆکسیدا کاربۆنێ (CO)",body:"CO کوژەرەکێ بێدەنگە:",points:["CO بێ ڕەنگ، بێ بێهن و بێ تامە — ب هەستان ناهێتە ناسین","نیشان: سەرئێشە، گێژبوون، دلتێکچوون و ڤەڕشاندن، تێکچوونا هشی؛ پاشان بێهۆشی و مرن","سەرچاڤە: سۆبەیێن غاز و نەفتێ ل ژوورێن بێ هەواگوهۆڕین","زڤستان مەترسیدارترین وەرزە، چونکی دەرگەهـ و پەنجەرە گرتینە","سنوورێ OSHA بۆ کارکەران ٥٠ ppm یە (تێکڕایا ٨ دەمژمێران)، لێ ل ژوورێن کاری دڤێت CO نێزیکی سفر بیت؛ هەر ڕێژەیەکا CO نیشانا کێماسیا هەواگوهۆڕینێ یە"]},{heading:"٢. ڕێسایێن هەواگوهۆڕینا دروست",body:"هەواگوهۆڕینا پێدڤی ل فەرمانگەهان:",points:["دەمێ سۆبەیا بێ بۆری کار دکەت، پەنجەرەکێ کێمەکێ ڤەکری بهێلە دا هەوایێ نوو بهێت","ژوورێن سۆبەیا ب بۆریا دوکێلێ (Chimney) تێدا: پانکا دەرێخستنا هەوایێ (Extractor Fan) د هەمان دەم دا کار پێ نەکە، هەتا تەکنیسیەنەکێ شارەزا پشتڕاست نەکەت کو دوکێلا سۆبەیێ هێشتا ب سەلامەتی دەردکەڤیت؛ پانکە دشێت دوکێلێ و غازا CO بکێشیتە ناڤ ژوورێ، هەتا ئەگەر پانکە د ژوورەکا دی دا بیت ژی","بۆریا دوکێلێ (Chimney): دڤێت ساخلەم و ڤەکری بیت، نە گرتی","کۆریدۆر و ڕێکێن دەرکەفتنێ ب سۆبەیان نەگرە","سۆبەیێن بێ بۆری بەری نڤستنێ و دەمێ ژوورێ ب جهـ دهێلی ڤەمرینە، و دەم دەم هەوایێ ژوورێ نوو بکە","مەتبەخ و تووالێت دڤێت هەواگوهۆڕینا تایبەت هەبیت"]},{heading:"٣. دەرکەفتنا غازێ — چ بکەم؟",body:"ئەگەر بێهنا غازێ هات:",points:["ئەگەر بشێی، د ڕێکا خوە یا دەرکەفتنێ دا پەنجەرە و دەرگەهان ڤەکە","چ شخاتە نەهەلکە و دەست ل سویچێن کارەبایێ نەدە (نە هەلکە و نە ڤەمرینە)!","مۆبایلێ ل ناڤ ئاڤاهیێ بکارنەئینە — چرسکەک دشێت تەقینێ چێبکەت","دەرکەڤە و هەمی کەسان دەربێخە","ژ دەرڤەی ئاڤاهیێ گازی ١١٥ بکە","تەنێ کارمەندێن ڕاهێنای و دەستنیشانکری غازێ ژ کێلۆنا سەرەکی دبڕن، ئەگەر گەهشتن بۆ وێ سەلامەت بیت و بێ چوونا د وی جهی دا یێ غاز لێ کۆم بوویە؛ چ جاران بۆ گەهشتنا وێ نەزڤڕە ژوور"]},{heading:"٤. پشکنینا هەیڤانە",body:"پشکنین:",points:["بۆریا دوکێلا سۆبەیێ بپشکنە — دڤێت گرتی نەبیت","گرێدانێن بۆریا غازێ ب ئاڤ و سابوونێ بپشکنە (تاقیکرنا کەفکێ)؛ چ جاران ب ئاگری نەپشکنە","ئامێرێ ناسینا CO (Carbon Monoxide Detector) دابنێ","تەکنیسیەنەکێ شارەزا هەر سال سۆبەیان بپشکنیت","تۆمارا پشکنینان بپارێزە"]}],media:[{kind:"video",src:"media/videos/gov_gas_safety.mp4",title:"مەترسیا غازێ",description:"چەوانیا ناسین و ڕێکاران"},{kind:"image",src:"media/images/gov_co_detector.png",title:"ئامێرێ ناسینا CO",description:"جهێ دانانێ"}],quiz:[{question:"CO (مۆنۆکسیدا کاربۆنێ) چ تایبەتمەندی هەیە؟",options:[{text:"بێهنەکا خراب هەیە",correct:!1},{text:"ڕەنگێ وێ سوورە",correct:!1},{text:"بێ ڕەنگ و بێ بێهنە",correct:!0},{text:"چ تایبەتمەندی نینن",correct:!1}],explanation:"CO بێ ڕەنگ، بێ بێهن و بێ تامە — ژبەر هندێ مەترسیدارە و ئامێرێ ناسینێ پێدڤییە."},{question:"ئەگەر بێهنا غازێ هات، ئێکەم کار چییە؟",options:[{text:"چرایێ کارەبایێ هەلکە",correct:!1},{text:"دەرکەڤە و د ڕێکا خوە دا پەنجەرەیان ڤەکە",correct:!0},{text:"مۆبایلێ بکاربینە",correct:!1},{text:"سۆبەیێ هەلکە",correct:!1}],explanation:"دەست ل ئاگر و سویچان نەدە، ئەگەر بشێی د ڕێکا خوە یا دەرکەفتنێ دا پەنجەرەیان ڤەکە، دەرکەڤە و ژ دەرڤە گازی ١١٥ بکە."},{question:"سۆبەیا غازێ یا بێ بۆری دڤێت کەنگی بهێتە ڤەمراندن؟",options:[{text:"تەنێ دەمێ غاز خلاس دبیت",correct:!1},{text:"بەری نڤستنێ و دەمێ ژوورێ ب جهـ دهێلی",correct:!0},{text:"تەنێ ل هاڤینێ",correct:!1},{text:"پێدڤی ب ڤەمراندنێ نینە",correct:!1}],explanation:"سۆبەیێن بێ بۆری چ جاران دەمێ نڤستنێ یان دەمێ کەس ل ژوورێ نەبیت هەلکری نەهێلە؛ دەم دەم هەوایێ ژوورێ نوو بکە."}]},{id:8,code:"GOV-108",icon:"Lock",accent:"#0891b2",title:"ئاسایشا سایبەری و داتایان",subtitle:"Cybersecurity & Data Protection",summary:"پاراستنا سیستەمێن کۆمپیوتەری و داتایێن حکومی ژ هێرشێن ئەلیکترۆنی و ڤایرۆسان",blocks:[{body:"د سەردەمێ دیجیتالی دا، هێرشێن سایبەری مەترسیەکا مەزنن بۆ فەرمانگەهێن حکومی. داتایێن تایبەت یێن خەلکی، بەلگەنامەیێن فەرمی و سیستەمێن دارایی هەمی دبنە ئارمانج. ئامادەبوون و ڕاهێنانا فەرمانبەران پێدڤییە."},{heading:"١. جۆرێن مەترسیا سایبەری",body:"مەترسیێن سەرەکی:",points:["فیشینگ (Phishing): ئیمەیل و نامێن ساختە کو دخوازن زانیاریان بدزن","ڤایرۆس و بەرنامێن زیانبار (Malware)","ڕانسۆموێر (Ransomware): قفلکرنا داتایان و داخوازکرنا پارەی","ئەندازیاریا جڤاکی (Social Engineering): خاپاندنا فەرمانبەران بۆ وەرگرتنا زانیاریان","تۆڕێن WiFi یێن نەپاراستی: دزینا زانیاریان ل سەر تۆڕێ","فلاشێن USB یێن نەناسیار: دشێن ڤایرۆسان بگوهێزن"]},{heading:"٢. ڕێسایێن پەیڤا نهێنی (Password)",body:"پەیڤا نهێنی یا ب هێز:",points:["درێژاهی: لایێ کێم ١٥ پیت و هێما (NIST SP 800-63B-4)","ڕستەکا درێژ ژ چەند پەیڤان (Passphrase) ب ساناهی دهێتە بیرا تە و ب هێزە","پەیڤا نهێنی ب دەمەکێ دیارکری نەگوهۆڕە؛ تەنێ دەمێ گومان هەبیت کو ئاشکرا بوویە بگوهۆڕە","ناڤ، ژمارا تەلەفۆنێ یان ١٢٣٤٥٦ بکارنەئینە","پشتڕاستکرنا دوو قۆناغی (2FA) چالاک بکە","بۆ هەر سیستەمەکی پەیڤەکا نهێنی یا جودا بکاربینە"]},{heading:"٣. ئیمەیلا سەلامەت",body:"چەوانیا پاراستنا خوە ل ئیمەیلێ:",points:["لینکێن نەناسیار ڤەنەکە — ناڤونیشانێ هنارتنکەری بپشکنە","فایلێن پێڤەکری ژ ناڤونیشانێن نەناسیار ڤەنەکە","ئەگەر ئیمەیلەکا گومانلێکری هات، بەشێ IT ئاگەهدار بکە","پەیڤا نهێنی و ژمارا حسابا بانکێ ب ئیمەیلێ نەهنێرە","تەنێ ئیمەیلا فەرمی بۆ کارێن فەرمانگەهێ بکاربینە"]},{heading:"٤. پاراستنا فیزیکی",body:"پاراستنا ئامێران:",points:["دەمێ ژ مێزێ دویر دکەڤی، کۆمپیوتەرێ خوە قفل بکە (Win+L)","نەهێلە کەسێن دی زانیاریان ل سەر شاشا تە ببینن","فلاشێن USB یێن نەناسیار نەخە ناڤ کۆمپیوتەری","کاغەزێن نهێنی ب ئامێرێ هویرکرنێ (Shredder) تێک بدە","مۆبایلێ کاری ب PIN یان پەنجەمۆرێ بپارێزە"]}],media:[{kind:"video",src:"media/videos/gov_cybersecurity.mp4",title:"ئاسایشا سایبەری",description:"بنەمایێن پاراستنێ"},{kind:"image",src:"media/images/gov_phishing.png",title:"ناسینا فیشینگێ",description:"نموونێن ئیمەیلێن ساختە"}],quiz:[{question:"فیشینگ (Phishing) چییە؟",options:[{text:"بەرنامەیەکێ باش",correct:!1},{text:"ئیمەیلێن ساختە بۆ دزینا زانیاریان",correct:!0},{text:"جۆرەکێ ئاگری",correct:!1},{text:"سیستەمێ کۆپیێن پاشکەفتی",correct:!1}],explanation:"فیشینگ ئیمەیلێن ساختەنە کو وەکی یێن فەرمی دیار دبن بۆ دزینا زانیاریان."},{question:"پەیڤا نهێنی یا ب هێز دڤێت لایێ کێم چەند پیت و هێما بیت؟",options:[{text:"٤",correct:!1},{text:"٦",correct:!1},{text:"٨",correct:!1},{text:"١٥",correct:!0}],explanation:"NIST (SP 800-63B-4) بۆ پەیڤا نهێنی یا بێ 2FA لایێ کێم ١٥ هێمایان دخوازیت؛ درێژاهی ژ تێکەلکرنا هێمایان گرنگترە."},{question:"ئەگەر فلاشەکا USB یا نەناسیار ل ئەردی دیت، چ بکەی؟",options:[{text:"بخە ناڤ کۆمپیوتەری",correct:!1},{text:"بدە بەرپرسێ IT",correct:!0},{text:"ببە مالێ",correct:!1},{text:"چ جوداهی نینە",correct:!1}],explanation:"فلاشێن نەناسیار دشێن ڤایرۆس تێدا هەبن — بدە بەشێ IT."}]},{id:9,code:"GOV-109",icon:"ShieldAlert",accent:"#7c3aed",title:"ئاسایشا کەسی و ڕێگرتن ل توندوتیژیێ",subtitle:"Personal Safety & Workplace Security",summary:"پاراستنا فەرمانبەران ژ مەترسیێن ئاسایشی و توندوتیژیا جهێ کاری",blocks:[{body:"سەلامەتیا فەرمانبەران تەنێ ئاگر و کارەبا نینە. توندوتیژی ل جهێ کاری، گەفکرن و ڕویدانێن ئاسایشی ژی پێدڤی ب ئامادەکاریێ نە. هەر فەرمانبەرەک دڤێت بزانیت چەوا ل ڤان ڕەوشان دا خوە بپارێزیت."},{heading:"١. مەترسیێن ئاسایشی ل فەرمانگەهان",body:"ڕەوشێن ئاسایشی:",points:["سەرەدانکەرێن تووڕە و نەڕازی","گەفکرنا فیزیکی","پاکەت و تشتێن گومانلێکری","هێرشا چەکداری، دزی یان تالانکرن","بارمتەگرتن","گەفکرن ب تەلەفۆنێ یان ب ئینتەرنێتێ"]},{heading:"٢. بڕەڤە، خوە ڤەشێرە، بێژە (Run, Hide, Tell)",body:"ئەگەر ڕویدانەکا ئاسایشی چێبوو:",points:["Run (بڕەڤە): ئەگەر ڕێکەکا سەلامەت هەبوو، ب لەز ژ ئاڤاهیێ دەرکەڤە","هەمیشە نێزیکترین ڕێکا دەرکەفتنێ بزانە","Hide (خوە ڤەشێرە): ئەگەر نەشیای بڕەڤی، ل ژوورەکێ خوە ڤەشێرە و دەرگەهی قفل بکە","مۆبایلێ خوە بێدەنگ بکە و لەرزینێ ژی ڤەمرینە","Tell (بێژە): دەمێ تو ل جهەکێ سەلامەت بووی، گازی ١٠٤ (پۆلیس) بکە","هەمی زانیاریان ب هویری بێژە: جهـ، ژمارا کەسان و وەسفا وان"]},{heading:"٣. مامەلەکرن دگەل سەرەدانکەرێن تووڕە",body:"ڕێکارێن ئارامکرنا ڕەوشێ:",points:["ب دەنگەکێ ئارام و نزم باخڤە","گوهداریێ بکە و نیشان بدە کو تو تێدگەهی","دویراتیەکا سەلامەت (١.٥-٢ مەتر) بپارێزە","هەمیشە ڕێکا دەرکەفتنا خوە ڤەکری بهێلە","هەڤکارەکی ئاگەهدار بکە دا بهێتە هاریکاریا تە","ئەگەر ڕەوش خرابتر بوو، دوگمەیا تەنگاڤیێ بگڤاشە یان گازی ١٠٤ بکە"]},{heading:"٤. ئامادەکاریا فەرمانگەهێ",body:"ئامادەکاریێن ئاسایشی:",points:["کامێرێن چاڤدێریێ (CCTV) دابنێ","سیستەمێ کۆنترۆلکرنا هاتنا ژوور (Access Control)","دوگمەیا تەنگاڤیێ (Panic Button) ل بن مێزێن پێشوازیێ","ڕاهێنانا فەرمانبەران هەر ٦ هەیڤان","پلانا ئاسایشی نوو بکە و تاقی بکە","پەیوەندیەکا ڕاستەوخوە دگەل نێزیکترین بنکەیا پۆلیسێ دابنێ"]}],media:[{kind:"video",src:"media/videos/gov_security.mp4",title:"ئاسایشا کەسی",description:"بڕەڤە، خوە ڤەشێرە، بێژە (Run, Hide, Tell)"},{kind:"image",src:"media/images/gov_deescalation.png",title:"ڕێکارێن ئارامکرنێ",description:"مامەلە دگەل سەرەدانکەرێن تووڕە"}],quiz:[{question:"د ڕێکارا Run, Hide, Tell دا، ئێکەم هەنگاڤ چییە؟",options:[{text:"خوە ڤەشێرە",correct:!1},{text:"بڕەڤە",correct:!0},{text:"بەرخودانێ بکە",correct:!1},{text:"گازی پۆلیسی بکە",correct:!1}],explanation:"ئێکەم کار: Run (بڕەڤە) ئەگەر ڕێکەکا سەلامەت هەبوو."},{question:"ل دەمێ مامەلەکرنێ دگەل سەرەدانکەرەکێ تووڕە، چ بکەی؟",options:[{text:"تو ژی ب دەنگێ بلند باخڤە",correct:!1},{text:"ب ئارامی باخڤە و گوهداریێ بکە",correct:!0},{text:"گوهـ نەدە وی",correct:!1},{text:"دەرگەهی ل سەر بگرە",correct:!1}],explanation:"ب ئارامی باخڤە و گوهداریێ بکە — ئەڤە ڕەوشێ ئارام دکەت."},{question:"ژمارا پۆلیسێ ل هەرێما کوردستانێ چەندە؟",options:[{text:"١١٥",correct:!1},{text:"١٢٢",correct:!1},{text:"١٠٤",correct:!0},{text:"٩١١",correct:!1}],explanation:"١٠٤ ژمارا پۆلیسێ یە ل هەرێما کوردستانێ."}]},{id:10,code:"GOV-110",icon:"Armchair",accent:"#16a34a",title:"ساخلەمی و سەلامەتیا جهێ کاری",subtitle:"Occupational Health & Ergonomics",summary:"پاراستنا ساخلەمیا فەرمانبەران ل جهێ کاری و ڕێکخستنا دروستا مێز و کورسیکێ",blocks:[{body:"فەرمانبەرێن حکومی گەلەک جاران ٨ دەمژمێران یان پتر ل بەر کۆمپیوتەری دڕوینن. ئەڤە دبیتە ئەگەرێ ئێشا پشتێ، چاڤان و ملان. ڕێکخستنا دروستا جهێ کاری (Ergonomics) و لڤینا فیزیکی ساخلەمیا کارمەندان دپارێزیت."},{heading:"١. ڕێکخستنا مێز و کورسیکێ (Ergonomics)",body:"جهێ کاری یێ دروست:",points:["کورسی: پشتەڤانیا پشتێ هەبیت؛ بلنداهیێ ڕێک بێخە هەتا پێ ب تەمامی ل سەر ئەردی بن","شاشە: سەرێ شاشێ ل ئاستێ چاڤان یان کێمەکێ نزمتر بیت، ب دویراتیا ٥٠-٧٠ سم","تەختەکلیل: ئانیشک ب گۆشەیەکا نێزیکی ٩٠° بن","ماوس: نێزیکی تەختەکلیلێ و ل هەمان ئاستی","بلنداهیا مێزێ: دڤێت دگەل بەژنا تە بگونجیت","ڕۆناهی: ڕۆناهی ڕاستەوخوە نەکەڤیتە سەر شاشێ"]},{heading:"٢. پاراستنا چاڤان",body:"ماندیبوونا چاڤان ژ شاشێ (Computer Vision Syndrome):",points:["ڕێسایا ٢٠-٢٠-٢٠: هەر ٢٠ خولەک، بۆ ٢٠ چرکەیان سەحکە تشتەکێ ٢٠ پێ (نێزیکی ٦ مەتر) دویر","چاڤان گەلەک جاران بلقینە — ل بەر شاشێ لقاندنا چاڤان کێم دبیت و چاڤ هشک دبن","ل ئێڤاران ڕۆناهیا شاشێ کێم بکە","مۆدا شەڤێ (Night Mode) چالاک بکە","چاڤێلکێن دژی ڕۆناهیا شین (Blue Light) چ مفایەکێ سەلماندی نینن (AAO)؛ ئەگەر چاڤێن تە هشک یان ماندی بوون، سەرەدانا پزیشکێ چاڤان بکە","هەر سال پشکنینا چاڤان بکە"]},{heading:"٣. ئێشا پشت و ملان",body:"ڕێگرتن و چارەسەری:",points:["هەر ٤٥ خولەک ڕابە و کێمەکێ بلڤە","ڕاکێشانا ستۆیێ: ب هێواشی سەری بەرەڤ ملان بچەمینە","ڕاکێشانا پشتێ: ل سەر کورسیکێ لەشێ خوە ب هێواشی بزڤڕینە","دەمێ گونجای بیت، ب پلەکانان بچە ل جهێ ئەسانسۆرێ","ب درێژاهیا ڕۆژێ ب ڕێکوپێکی ئاڤێ ڤەخوە","ڕوینشتنا دروست: پشت ڕاست، مل ئارام، پێ ل سەر ئەردی"]},{heading:"٤. ساخلەمیا دەروونی",body:"سەلامەتیا دەروونی یا فەرمانبەران:",points:["فشارا کاری (Stress): ئەگەرێن سەرەکی بناسە","ڕێکخستنا دەمی: دەمێ کاری و دەمێ بێهنڤەدانێ ژێک جودا بکە","ئاخفتن: دگەل هەڤکارێن خوە دەربارەی ئاریشان باخڤە","هەر ڕۆژ ١٥ خولەک ل دەرڤە بێهنا خوە ڤەدە","ل دەمێ بێهنڤەدانێ مۆبایلێ بۆ کاری بکارنەئینە","ئەگەر نیشان بەردەوام بوون: پەیوەندیێ ب پسپۆرەکێ ساخلەمیا دەروونی ڤە بکە"]}],media:[{kind:"video",src:"media/videos/gov_ergonomics.mp4",title:"ئێرگۆنۆمی (Ergonomics)",description:"ڕێکخستنا مێز و کورسیکێ"},{kind:"image",src:"media/images/gov_posture.png",title:"ڕوینشتنا دروست",description:"وێنەیەکێ ڕێنمایی"},{kind:"image",src:"media/images/gov_eye_care.png",title:"ڕێسایا ٢٠-٢٠-٢٠",description:"پاراستنا چاڤان"}],quiz:[{question:"ڕێسایا ٢٠-٢٠-٢٠ بۆ چییە؟",options:[{text:"پاراستنا گوهان",correct:!1},{text:"پاراستنا چاڤان",correct:!0},{text:"پاراستنا پشتێ",correct:!1},{text:"پاراستنا دەستان",correct:!1}],explanation:"هەر ٢٠ خولەک، بۆ ٢٠ چرکەیان سەحکە تشتەکێ ٢٠ پێ (نێزیکی ٦ مەتر) دویر — بۆ پاراستنا چاڤان (AAO)."},{question:"شاشا کۆمپیوتەری دڤێت چەند ژ چاڤان دویر بیت؟",options:[{text:"٢٠-٣٠ سم",correct:!1},{text:"٣٠-٤٠ سم",correct:!1},{text:"٥٠-٧٠ سم",correct:!0},{text:"١ مەتر",correct:!1}],explanation:"دویراتیا ٥٠-٧٠ سم (نێزیکی درێژاهیا دەستی) گونجایترە."},{question:"فەرمانبەر دڤێت هەر چەند خولەک ژ بەر مێزێ ڕابن و بلڤن؟",options:[{text:"٢٠ خولەک",correct:!1},{text:"٤٥ خولەک",correct:!0},{text:"٢ دەمژمێر",correct:!1},{text:"١ دەمژمێر",correct:!1}],explanation:"پێشنیار دهێتە کرن کو هەر ٤٥ خولەک ڕابی و کێمەکێ بلڤی."}]},{id:11,code:"GOV-111",icon:"Waves",accent:"#2563eb",title:"لافاو و زیانێن ئاڤێ",subtitle:"Flood Response & Water Damage",summary:"ئامادەبوون و بەرسڤدانا لافاو و زیانێن ئاڤێ ل فەرمانگەهان",blocks:[{body:"ئاڤ دشێت ژ چەند سەرچاڤەیان بگەهیتە فەرمانگەهان: باران و لافاوێن سروشتی، تەقینا بۆریێن ئاڤێ، ئاریشێن سیستەمێ کۆندیشنێ، یان ڕژانا ئاڤێ ژ قاتێ سەری. ئامادەبوون و هشیاری زیانێ کێم دکەن."},{heading:"١. سەرچاڤەیێن ئاڤێ ل فەرمانگەهان",body:"ئاڤ ژ کیرێ دهێت:",points:["باران و لافاوێن سروشتی: ب تایبەتی ل ناڤچەیێن نزم","تەقینا بۆریێن ئاڤێ: بۆریێن کەڤن و ژەنگگرتی","حەلیانا بەفرێ: بەفر دبیتە ئاڤ و دچیتە ناڤ ئاڤاهیێ","ڕژانا ئاڤێ ژ قاتێ سەری: ژ تووالێت و مەتبەخێ","سیستەمێ کۆندیشنێ: ئاڤا کۆمبووی و ڕژان","تانکیێن ئاڤێ: تەقین یان ڕژانا تانکیێ"]},{heading:"٢. بەری لافاوێ — ئامادەکاری",body:"ئامادەکاریێن پێدڤی:",points:["بەلگەنامەیێن گرنگ ل قاتێن سەری و د دۆلابێن بلند دا بهێلە","کۆمپیوتەران ل سەر ئەردی دانەنێ — لایێ کێم ٣٠ سم بلندتر ژ ئەردی","وایەرێن کارەبایێ ل سەر ئەردی نەبن","نەخشەیا بۆریان و جهێ کێلۆنا سەرەکی یا ئاڤێ بزانە","پەمپا ڤالاکرنا ئاڤێ (Sump Pump) ئامادە بکە","لیستا ژمارێن تەکنیکی و تەنگاڤیێ ئامادە بهێلە"]},{heading:"٣. ل دەمێ لافاوێ",body:"ئەگەر ئاڤ هاتە ناڤ فەرمانگەهێ:",points:["ئەگەر تو ل ناڤ ئاڤێ نەبی و ب سەلامەتی دگەهیە سویچێ، کارەبایا سەرەکی ببڕە — کارەبا و ئاڤ پێکڤە کوژەرن","گازی ١١٥ بکە و بەرپرسێ ئاڤاهیێ ئاگەهدار بکە","هەمی فەرمانبەر ب سەلامەتی بۆ جهەکێ بلند دەرکەڤن","ئەگەر ئاڤ کێم بوو: بەلگەنامە و کۆمپیوتەران بۆ جهەکێ بلند بگوهێزە","نەچە ناڤ ئاڤا لافاوێ: ١٥ سم ئاڤا ب لەز دشێت مرۆڤی بکەڤینیت و ٣٠ سم دشێت ترومبێلێ ببەت؛ مەترسیا کارەبایێ و نەخۆشیان ژی هەیە","کێلۆنا سەرەکی یا ئاڤێ ببڕە"]},{heading:"٤. پشتی لافاوێ",body:"پشتی ئاڤ کێم بوو:",points:["پشکنینا ئاڤاهیێ: بەری زڤڕینێ، شارەزا ئاڤاهیێ بپشکنیت","کارەبایێ هەلنەکە هەتا تەکنیسیەن پشتڕاست نەکەت کو سەلامەتە","دژەمیکرۆبکرن (Disinfection): ئاڤا لافاوێ پیسە و باکتریا و نەخۆشیان دگوهێزیت","هەواگوهۆڕین: هەمی پەنجەرە و دەرگەهان ڤەکە","وێنەیان بگرە بۆ تۆمارکرن و بیمێ","تشتێن زیاندیتی ب سەلامەتی لابە"]}],media:[{kind:"video",src:"media/videos/gov_flood_response.mp4",title:"بەرسڤدانا لافاوێ",description:"چ بکەین دەمێ ئاڤ دهێت"},{kind:"image",src:"media/images/gov_flood_prep.png",title:"ئامادەکاریا لافاوێ",description:"هەنگاڤ ب هەنگاڤ"}],quiz:[{question:"ل دەمێ لافاوێ ل فەرمانگەهێ، ئێکەم کار چییە؟",options:[{text:"بەلگەنامەیان کۆم بکە",correct:!1},{text:"کارەبایا سەرەکی ببڕە (ئەگەر سەلامەت بوو)",correct:!0},{text:"وێنەیان بگرە",correct:!1},{text:"ب تەلەفۆنێ باخڤە",correct:!1}],explanation:"کارەبا و ئاڤ پێکڤە مەترسیا مرنێ چێدکەن. ئەگەر تو ل ناڤ ئاڤێ نەبی و ب سەلامەتی دگەهیە سویچێ، ئێکسەر کارەبایا سەرەکی ببڕە؛ ئەگەر نە، دەرکەڤە و گازی ١١٥ بکە."},{question:"بەلگەنامەیێن گرنگ ل فەرمانگەهەکا ل بەر مەترسیا لافاوێ ل کیرێ بهێلین؟",options:[{text:"ل سەر ئەردی",correct:!1},{text:"ل قاتێ ژێرێ",correct:!1},{text:"ل قاتێن سەری و د دۆلابێن بلند دا",correct:!0},{text:"چ جوداهی نینە",correct:!1}],explanation:"هەمیشە بەلگەنامەیێن گرنگ ل جهەکێ بلند و سەلامەت بهێلە."},{question:"بۆچی پشتی لافاوێ دژەمیکرۆبکرن پێدڤییە؟",options:[{text:"بۆ بێهنا خوەش",correct:!1},{text:"ئاڤا لافاوێ باکتریا و نەخۆشیان دگوهێزیت",correct:!0},{text:"بۆ جوانیێ",correct:!1},{text:"پێدڤی نینە",correct:!1}],explanation:"ئاڤا لافاوێ گەلەک پیسە و باکتریا و نەخۆشیان دگوهێزیت."}]},{id:12,code:"GOV-112",icon:"FlaskConical",accent:"#65a30d",title:"ماددێن کیمیایی و پاقژکرنێ",subtitle:"Chemical Safety & Cleaning Agents",summary:"بکارئینانا سەلامەت یا ماددێن پاقژکرنێ و کیمیایی ل فەرمانگەهان",blocks:[{body:"فەرمانگەهێن حکومی گەلەک جۆرێن ماددێن پاقژکرنێ بکاردئینن. تێکەلکرنا هندەک ژ ڤان ماددان دشێت غازێن ژەهراوی و مەترسیدار چێبکەت. ناسینا ماددان و بکارئینانا دروست ژیانێ ڕزگار دکەت."},{heading:"١. ماددێن مەترسیدار ل فەرمانگەهان",body:"ئەڤ ماددە ل گەلەک فەرمانگەهان هەنە:",points:["کلۆر (Bleach): بۆ پاقژکرنا تووالێتان — ئەگەر دگەل ئاسید یان ئەمۆنیاکێ تێکەل ببیت، غازێن ژەهراوی چێدکەت","ئەمۆنیاک: بۆ پاقژکرنا پەنجەرەیان — زیانێ دگەهینیتە هەناسەدانێ","ئاسید: بۆ لابرنا کلسێ — پێستی دسوژیت","تۆنەرێ چاپکەران: تۆزەکا هویر — مەترسی بۆ سییان","شلەیا ڕاستکرنا نڤیسینێ (Correction Fluid): ئاگر دگریت و هەلمێن وێ زیانبارن","ئاسیدا باتریان: سووتنا کیمیایی"]},{heading:"٢. ڕێسایا تێکەلنەکرنێ!",body:"چ جاران ئەڤان ماددان تێکەل نەکە:",points:["کلۆر + ئەمۆنیاک = غازا کلۆرامینێ (ژەهراوی و کوژەر)","کلۆر + ئاسید = غازا کلۆرینێ (ژەهراوی و کوژەر)","کلۆر + سرکە (کو ئاسیدە) = غازا کلۆرینێ","هەر ماددەیەکێ ب تنێ بکاربینە","تەنێ ب ئاڤێ ڕوون بکە، ل دویڤ ڕێنماییێن سەر قوتیێ — نە ب ماددەکا دی","هەمیشە ڕێنماییێن سەر قوتیێ (Label) بخوینە"]},{heading:"٣. کەرەستێن پاراستنا کەسی (PPE)",body:"کەرەستێن پاراستنێ ل دەمێ بکارئینانا ماددان:",points:["دەستکێش: بۆ هەمی ماددێن کیمیایی پێدڤینە","ماسک: دەمێ کلۆر و ماددێن بێهندار بکاردئینی","چاڤێلکێن پاراستنێ: بۆ ئاسید و سپرێیان","بەرگێ پاراستنێ: بۆ ماددێن ب هێز","ئەگەر ماددە کەفتە سەر پێستی یان چاڤان: لایێ کێم ٢٠ خولەک ب ئاڤا ڕەوان بشۆ؛ ئەگەر سووتن یان ژەهربوون هەبوو گازی ١٢٢ بکە","هەواگوهۆڕین: دەمێ پاقژکرنێ پەنجەرێ ڤەکە"]},{heading:"٤. هەلگرتن و لابرنا ماددان",body:"ڕێسایێن هەلگرتنا ماددان:",points:["ل جهەکێ قفلکری بهێلە","دویر ژ تاڤ و گەرمیێ","ناڤێ ماددێ ل سەر هەمی شیشە و قوتیان بنڤیسە","پەڕێن داتایێن سەلامەتیێ (SDS) ئامادە بهێلە","ماددێن بەسەرچووی ب ڕێکا دروست لابە — نەڕێژە ناڤ لوولێن ئاڤا پیس","دویر ژ خوارن و ئاڤا ڤەخوارنێ بهێلە"]}],media:[{kind:"video",src:"media/videos/gov_chemical_safety.mp4",title:"سەلامەتیا کیمیایی",description:"بکارئینانا دروست"},{kind:"image",src:"media/images/gov_mixing_danger.png",title:"مەترسیا تێکەلکرنێ",description:"کیژ ماددە نابیت تێکەل ببن"},{kind:"image",src:"media/images/gov_ppe_cleaning.png",title:"PPE بۆ پاقژکرنێ",description:"کەرەستێن پاراستنێ"}],quiz:[{question:"چ چێدبیت ئەگەر کلۆر و ئەمۆنیاک تێکەل بکەین؟",options:[{text:"پاقژکەرەکێ باشتر چێدبیت",correct:!1},{text:"غازا کلۆرامینێ (ژەهراوی) چێدبیت",correct:!0},{text:"چ نابیت",correct:!1},{text:"بێهنەکا خوەش چێدبیت",correct:!1}],explanation:"تێکەلکرنا کلۆر و ئەمۆنیاکێ غازا کلۆرامینێ چێدکەت — مەترسیا مرنێ هەیە."},{question:"ئەگەر ماددەکا کیمیایی کەفتە سەر پێستی، چ بکەین؟",options:[{text:"ب دەسمالێ پاقژ بکە",correct:!1},{text:"لایێ کێم ٢٠ خولەک ب ئاڤێ بشۆ",correct:!0},{text:"کرێمێ ل سەر بدە",correct:!1},{text:"چ نەکە",correct:!1}],explanation:"ئێکسەر لایێ کێم ٢٠ خولەک ب ئاڤا ڕەوان بشۆ و جلێن پیس بوویی لابە؛ ئەگەر سووتن هەبوو گازی ١٢٢ بکە."},{question:"ماددێن پاقژکرنێ ل فەرمانگەهێ ل کیرێ بهێلین؟",options:[{text:"ل سەر مێزێ",correct:!1},{text:"نێزیکی خوارنێ",correct:!1},{text:"ل جهەکێ قفلکری و دویر ژ گەرمیێ",correct:!0},{text:"چ جوداهی نینە",correct:!1}],explanation:"ل جهەکێ قفلکری، دویر ژ گەرمیێ و خوارنێ بهێلە."}]},{id:13,code:"GOV-113",icon:"ArrowUpDown",accent:"#4f46e5",title:"سەلامەتیا ئەسانسۆر و پلەکانان",subtitle:"Elevator & Stairway Safety",summary:"بکارئینانا سەلامەت یا ئەسانسۆرێ و ڕێگرتن ل کەفتنێ ل سەر پلەکانان",blocks:[{body:"ئەسانسۆر و پلەکانێن ئاڤاهیێ ژ جهێن بەلاڤ یێن ڕویدانان ل ئاڤاهیێن حکومی نە. کەفتن ل سەر پلەکانان ئێک ژ بەلاڤترین ڕویدانێن جهێ کاری یە، و مانا ل ناڤ ئەسانسۆرێ ڕەوشەکا جددی یە. زانینا ڕێسایان مەترسیێ کێم دکەت."},{heading:"١. سەلامەتیا ئەسانسۆرێ",body:"ڕێسایێن بکارئینانا ئەسانسۆرێ:",points:["ئەگەر ئەسانسۆر درەنگ هات، سەبرێ بکە — دوگمێ گەلەک جاران نەگڤاشە","دەرگەهێ ئەسانسۆرێ ب دەستی ڤەنەکە — بهێلە ب خوە ڤەبیت","ژ بارێ دەستووری (کو ل سەر هاتیە نڤیسین) پتر بار نەکە","ل دەمێ بڕینا کارەبایێ بکارنەئینە","ل دەمێ ئاگر و عەردەهەژینێ بکارنەئینە — تەنێ ب پلەکانان","بزانە دوگمەیا تەنگاڤیێ ل کیرێ یە"]},{heading:"٢. مانا ل ناڤ ئەسانسۆرێ",body:"ئەگەر ل ناڤ ئەسانسۆرێ مای:",points:["ئارام بە — نەترسە","دوگمەیا تەنگاڤیێ بگڤاشە","تەلەفۆنا ناڤ ئەسانسۆرێ بکاربینە","ئەگەر تۆڕا مۆبایلێ هەبوو، گازی ١١٥ بکە","هەولا ڤەکرنا دەرگەهی یان دەرکەفتنێ نەدە — مەترسیدارە","چاڤەڕێ بە هەتا تەکنیسیەن یان تیمێ ١١٥ دگەهیت — هەوا ل ناڤ ئەسانسۆرێ خلاس نابیت"]},{heading:"٣. سەلامەتیا پلەکانان",body:"ڕێگرتن ل کەفتنێ ل سەر پلەکانان:",points:["هەمیشە دەسکێ پلەکانان (Handrail) بگرە","سەحکە بەر پێیێن خوە — مۆبایلێ بکارنەئینە","هەنگاڤ ب هەنگاڤ — باز نەدە","ل سەر پلەکانێن تەڕ ب هشیاری بچە","دەمێ بار هەلدگری، دەستەکێ ئازاد بهێلە بۆ گرتنا دەسکی","ڕۆناهیا پلەکانان دڤێت باش بیت — لامپێن سووتی بگوهۆڕە"]},{heading:"٤. پشکنین و چاککرن",body:"پشکنینێن ب ڕێکوپێک:",points:["ئەسانسۆر: چاککرنا هەیڤانە ژ لایێ کۆمپانیەکا شارەزا ڤە و پشکنینا سالانە ژ لایێ لایەنەکێ پەسەندکری ڤە","بەلگەنامەیا پشکنینێ ل ناڤ ئەسانسۆرێ هەلاویسە","ڕۆناهیا تەنگاڤیێ یا پلەکانان بپشکنە","پلەکانێن شکەستی ئێکسەر چاک بکە","ل جهێن خلیسکی نیشانا ئاگەهداریێ دابنێ","پلەکانان پاقژ بهێلە — چ تشتان ل سەر پلەکانان نەهێلە"]}],media:[{kind:"video",src:"media/videos/gov_elevator_safety.mp4",title:"سەلامەتیا ئەسانسۆرێ",description:"بکارئینانا دروست و مانا ل ناڤ دا"},{kind:"image",src:"media/images/gov_stair_safety.png",title:"سەلامەتیا پلەکانان",description:"ڕێسایێن ڕێگرتنا کەفتنێ"}],quiz:[{question:"ل دەمێ ئاگرکەفتنێ، بۆ دەرکەفتنێ چ بکاربینین؟",options:[{text:"ئەسانسۆر",correct:!1},{text:"پلەکانێن ئاڤاهیێ",correct:!0},{text:"چ جوداهی نینە",correct:!1},{text:"پەنجەرە",correct:!1}],explanation:"ل دەمێ ئاگر و عەردەهەژینێ چ جاران ئەسانسۆرێ بکارنەئینە — تەنێ ب پلەکانان دەرکەڤە."},{question:"ئەگەر ل ناڤ ئەسانسۆرێ مای، چ بکەی؟",options:[{text:"هەولا ڤەکرنا دەرگەهی بدە",correct:!1},{text:"ب ترس قێڕی بکە",correct:!1},{text:"دوگمەیا تەنگاڤیێ بگڤاشە و ئارام بە",correct:!0},{text:"باز بدە",correct:!1}],explanation:"ئارام بە و دوگمەیا تەنگاڤیێ بگڤاشە. هەولا ڤەکرنا دەرگەهی نەدە."},{question:"بۆ ڕێگرتن ل کەفتنێ ل سەر پلەکانان، چ بکەین؟",options:[{text:"باز بدە",correct:!1},{text:"مۆبایلێ بکاربینە",correct:!1},{text:"دەسکێ پلەکانان بگرە و سەحکە بەر پێیێن خوە",correct:!0},{text:"چاڤێن خوە بگرە",correct:!1}],explanation:"هەمیشە دەسکێ پلەکانان بگرە و سەحکە بەر پێیێن خوە."}]},{id:14,code:"GOV-114",icon:"Network",accent:"#e11d48",title:"ڕێڤەبرنا قەیرانان",subtitle:"Crisis Management & ICS",summary:"دامەزراندنا تیمێ ڕێڤەبرنا قەیرانان و سیستەمێ فەرماندەیا ڕویدانێ (ICS)",blocks:[{body:"هەر فەرمانگەهەکا حکومی دڤێت تیمەکێ ڕێڤەبرنا قەیرانان (Crisis Management Team) هەبیت. قەیران دشێت ئاگر، عەردەهەژین، لافاو، هێرشەکا ئاسایشی یان حەتا هێرشەکا سایبەری بیت. سیستەمێ فەرماندەیا ڕویدانێ (ICS) ئامرازەکێ نێڤدەولەتی یە بۆ ڕێڤەبرنا هەر ڕویدانەکێ."},{heading:"١. تیمێ ڕێڤەبرنا قەیرانان (CMT)",body:"پێکهاتا تیمی:",points:["سەرۆکێ تیمی (Crisis Commander): بڕیاردەر و ئاراستەکەر","بەرپرسێ کاران (Operations): ڕێکخستنا چالاکیان","بەرپرسێ ڕاگەهاندنێ: پەیوەندی دگەل لایەنێن دەرڤە و میدیا","بەرپرسێ لۆجستیکێ: پێدڤی و ئامێر","بەرپرسێ داتایان: تۆمارکرنا ڕویدانان","بەرپرسێ هەوارهاتنا ئێکێ: هاریکاریا برینداران"]},{heading:"٢. سیستەمێ فەرماندەیا ڕویدانێ (ICS)",body:"ICS (Incident Command System):",points:["ل ئەمریکا هاتیە چێکرن و نوکە ل گەلەک وەلاتان دهێتە بکارئینان","ئێک فەرماندەرێ ڕویدانێ — زنجیرا فەرماندەییێ ڕوونە","دیارکرنا ئەرکان: هەر کەسەک ئەرکێ خوە دزانیت و ب ئێک سەرپەرشتیار ڤە گرێدایە","ڕاگەهاندنا ئێکگرتی: ئێک کەنالێ پەیوەندیێ و زمانێ ساددە","ڕێکخستنا نەرم (Modular): ڕێکخستن ل دویڤ مەزناهیا ڕویدانێ مەزن یان بچووک دبیت","ڕاپۆرت: نووکرنا ڕاپۆرتان ل دەمێن دیارکری"]},{heading:"٣. هەنگاڤێن بەرسڤدانا قەیرانێ",body:"ڕێکارا گشتی:",points:["١. ئاگەهدارکرن: سیستەمێ ئاگەهدارکرنێ چالاک بکە","٢. هەلسەنگاندن: بزانە چ چێبوویە و مەزناهیا وێ چەندە","٣. چالاککرن: تیمێ CMT کۆم بکە","٤. ڕێڤەبرن: بڕیاران بدە و جێبەجێ بکە","٥. ڕاگەهاندن: هەمی لایەنان ئاگەهدار بکە","٦. ڤەگەڕیان: پلانا زڤڕینێ بۆ کارێ ئاسایی جێبەجێ بکە"]},{heading:"٤. ڕاهێنان و تاقیکرن",body:"ئامادەکاریا بەردەوام:",points:["هەر ٣ هەیڤان ڕاهێنانا ل سەر مێزێ (Tabletop Exercise)","هەر ٦ هەیڤان ڕاهێنانا تەمام (Full-Scale Drill)","نووکرنا پلانا قەیرانێ هەر سال","تاقیکرنا سیستەمێ ڕاگەهاندنێ","هاریکاری دگەل بەرگرییا شارستانی (١١٥) و پۆلیسی (١٠٤)","پشتی هەر ڕاهێنانەکێ هەلسەنگاندنێ بکە و کاری باشتر بکە"]}],media:[{kind:"video",src:"media/videos/gov_crisis_management.mp4",title:"ڕێڤەبرنا قەیرانان",description:"سیستەمێ ICS و تیمێ CMT"},{kind:"image",src:"media/images/gov_ics_chart.png",title:"خشتەیا ICS",description:"پێکهاتا فەرماندەییێ"}],quiz:[{question:"د سیستەمێ ICS دا، چەند فەرماندەرێن ڕویدانێ هەنە؟",options:[{text:"٣",correct:!1},{text:"٥",correct:!1},{text:"١ (ئێک)",correct:!0},{text:"١٠",correct:!1}],explanation:"د ICS دا ئێک فەرماندەرێ ڕویدانێ هەیە، دا زنجیرا فەرماندەییێ ڕوون بیت. ئەگەر چەند لایەن بەشدار بن، فەرماندەیا ئێکگرتی (Unified Command) ب ئێک پلانێ کار دکەت."},{question:"ل دویڤ ڤێ بەرنامەیێ، ڕاهێنانا ل سەر مێزێ (Tabletop) هەر چەند جاران پێدڤییە؟",options:[{text:"هەر سالەکێ",correct:!1},{text:"هەر ٦ هەیڤان",correct:!1},{text:"هەر ٣ هەیڤان",correct:!0},{text:"تەنێ ئێک جار",correct:!1}],explanation:"ئەڤ بەرنامە پێشنیار دکەت هەر ٣ هەیڤان ڕاهێنانا ل سەر مێزێ بهێتە کرن."},{question:"ئێکەم هەنگاڤ د بەرسڤدانا قەیرانێ دا چییە؟",options:[{text:"ڕێڤەبرن",correct:!1},{text:"ڕاگەهاندن",correct:!1},{text:"ئاگەهدارکرن و چالاککرنا سیستەمێ ئاگەهدارکرنێ",correct:!0},{text:"ڤەگەڕیان",correct:!1}],explanation:"ئێکەم هەنگاڤ: ئاگەهدارکرن — سیستەمێ ئاگەهدارکرنێ چالاک بکە."}]},{id:15,code:"GOV-115",icon:"Megaphone",accent:"#c026d3",title:"ڕاگەهاندن ل دەمێ تەنگاڤیێ",subtitle:"Emergency Communication",summary:"سیستەمێ ڕاگەهاندن و ئاگەهدارکرنێ ل دەمێ ڕویدانان",blocks:[{body:"ل دەمێ ڕویدانان، ڕاگەهاندنا دروست و ب لەز ژیانێ ڕزگار دکەت. د گەلەک ڕویدانان دا، نەبوونا ڕاگەهاندنەکا باش قوربانی زێدە کرینە. هەر فەرمانگەهەکا حکومی دڤێت سیستەمەکێ ڕاگەهاندنێ یێ ب هێز هەبیت."},{heading:"١. سیستەمێن ئاگەهدارکرنێ",body:"چەند سیستەم هەنە:",points:["سیرێنا ناڤخوەیی: زەنگا ئاگری و تەنگاڤیێ","سیستەمێ بلندگۆیێ (PA System): بۆ هنارتنا پەیامان بۆ هەمی قاتان","نامێن مۆبایلێ (SMS Group): بۆ فەرمانبەران","ئیمەیلا ب لەز: بۆ ئاگەهداریێن فەرمی","گرووپێن واتسئەپ و تێلیگرامێ: بۆ هەماهەنگیا ب لەز","ڕادیۆیا دوو-ئالی (Walkie-Talkie): بۆ تیمێ تەنگاڤیێ"]},{heading:"٢. زنجیرا ڕاگەهاندنێ",body:"کێ پەیامێ دهنێریت:",points:["١. ئاگەهدارکەر: ئەو کەسێ ڕویدان دیتی — ئێکسەر گازی ١١٥ دکەت (و ١٢٢ ئەگەر بریندار هەبن)","٢. بەرپرسێ قاتی: فەرمانبەرێ بەرپرس ل قات و ژووران","٣. فەرماندەرێ قەیرانێ: بڕیاردان و ئاراستەکرن","٤. بەرپرسێ ڕاگەهاندنێ: پەیوەندی دگەل ١١٥ و لایەنێن دەرڤە","٥. ڕێڤەبەرێ فەرمانگەهێ: ئاگەهدارکرنا ئاستێ بلندتر","هەمی پەیام دڤێت هویر بن و زانیاریێن تەمام تێدا بن"]},{heading:"٣. ناڤەرۆکا پەیاما تەنگاڤیێ",body:"پەیامەکا باش ئەڤان تێدایە:",points:["جهـ: ل کیرێ چێبوو (ئاڤاهی، قات، ژوور)","چ: چ چێبوو (ئاگر، عەردەهەژین، هێرش...)","کەس: چەند کەس بریندار بووینە یان ل جهی مای نە","مەترسی: ئەرێ مەترسیەکا بەردەوام هەیە؟","پێدڤی: چ هاریکاری پێدڤییە","پەیوەندی: ژمارا تەلەفۆنا تە بۆ پەیوەندیکرنێ"]},{heading:"٤. ڕاگەهاندن دگەل لایەنێن دەرڤە",body:"پەیوەندی دگەل لایەنێن دەرڤە:",points:["١١٥ — بەرگرییا شارستانی: ئاگر و ڕزگارکرن","١٢٢ — ئەمبوولانس: برینداری و نەخۆشی","١٠٤ — پۆلیس: ڕەوشێن ئاسایشی","میدیا: تەنێ بەرپرسێ ڕاگەهاندنێ دئاخڤیت","خێزانێن فەرمانبەران: ئاگەهدارکرن ب ساناهیترین ڕێک","ڕێڤەبەرایەتیا گشتی: ڕاپۆرتا فەرمی"]},{heading:"٥. تاقیکرنا سیستەمی",body:"پشکنینا بەردەوام:",points:["هەر هەیڤ سیرێنا ناڤخوەیی تاقی بکە","هەر حەفتی پەیامەکا تاقیکرنێ بۆ گرووپێ بهنێرە","باتری و مەودایێ ڕادیۆیێن دوو-ئالی بپشکنە","لیستا ژمارێن تەنگاڤیێ نوو بکە","پشتی هەر ڕاهێنانەکێ سیستەمێ ڕاگەهاندنێ هەلسەنگینە","پلانا جهگر: ئەگەر سیستەمەک کار نەکر، جهگرێ وی چییە؟"]}],media:[{kind:"video",src:"media/videos/gov_emergency_comm.mp4",title:"ڕاگەهاندنا تەنگاڤیێ",description:"سیستەمێ ڕاگەهاندنێ و زنجیرا وی"},{kind:"image",src:"media/images/gov_comm_chain.png",title:"زنجیرا ڕاگەهاندنێ",description:"کێ پەیوەندیێ ب کێ ڤە دکەت"},{kind:"image",src:"media/images/gov_message_template.png",title:"نموونەیا پەیامێ",description:"ناڤەرۆکا پەیاما دروست"}],quiz:[{question:"ل دەمێ تەنگاڤیێ، کیژ سیستەم ب لەزترینە بۆ ئاگەهدارکرنا هەمی قاتان؟",options:[{text:"ئیمەیل",correct:!1},{text:"واتسئەپ",correct:!1},{text:"سیستەمێ بلندگۆیێ (PA)",correct:!0},{text:"نامەیا کاغەزی",correct:!1}],explanation:"سیستەمێ PA ب لەزترینە چونکی ئێکسەر ل هەمی قاتان دهێتە بهیستن."},{question:"پەیاما تەنگاڤیێ دڤێت چ زانیاری تێدا بن؟",options:[{text:"تەنێ جهـ",correct:!1},{text:"تەنێ ژمارا برینداران",correct:!1},{text:"جهـ، چ چێبوو، کەس، مەترسی، پێدڤی",correct:!0},{text:"تەنێ ژمارا ١١٥",correct:!1}],explanation:"پەیاما تەمام: جهـ + چ چێبوو + کەس + مەترسی + پێدڤی + ژمارا پەیوەندیێ."},{question:"ل دەمێ قەیرانێ، کێ دەستوورا ئاخفتنێ دگەل میدیا هەیە؟",options:[{text:"هەر فەرمانبەرەک",correct:!1},{text:"تەنێ بەرپرسێ ڕاگەهاندنێ",correct:!0},{text:"سەرەدانکەر",correct:!1},{text:"تەنێ پۆلیس",correct:!1}],explanation:"تەنێ بەرپرسێ ڕاگەهاندنێ دەستوورا ئاخفتنێ دگەل میدیا هەیە، دا زانیاریێن خەلەت بەلاڤ نەبن."}]},{id:16,code:"GOV-116",icon:"Heart",accent:"#db2777",title:"هەوارهاتنا ئێکێ و CPR",subtitle:"First Aid & CPR — Complete Training",summary:"ڕاهێنانا تەمام ل سەر هەوارهاتنا ئێکێ، CPR و بەرسڤدانا تەنگاڤیێ ل فەرمانگەهان",blocks:[{body:"هەوارهاتنا ئێکێ (First Aid) ئەو هاریکاریا دەستپێکێ یە کو بەری گەهشتنا تیمێن پزیشکی دهێتە دان بۆ کەسێ بریندار یان نەخۆش. ل فەرمانگەهان مەترسیا ئاگر، عەردەهەژین و نەخۆشیێن ژنشکەکێ هەیە. هەر فەرمانبەرەک دڤێت بزانیت چەوا CPR بکەت، خوینبەربوونێ ڕاوەستینیت و بریندارەکی بپارێزیت هەتا ئەمبوولانس (١٢٢) دگەهیت."},{heading:"١. CPR — زیندیکرنا دل و سییان",body:"CPR ڕێکارەکا ڕزگارکرنا ژیانێ یە دەمێ دلێ مرۆڤی یان هەناسەدانا وی ڕادوەستیت:",points:["١. سەلامەتیا جهی: ئەرێ جهـ سەلامەتە؟ (کارەبا، ئاگر یان غاز نینن؟)","٢. بەرسڤ: ملێن وی ب هێواشی بلەقینە و ب دەنگەکێ بلند بپرسە: «تو باشی؟ تو گوهـ ل من دبی؟»","٣. گازی ١٢٢ بکە: ئەگەر بەرسڤ نەدا و ب دروستی هەناسە نەدا، ئێکسەر گازی ١٢٢ بکە و AED بینە یان داخواز بکە","٤. فشارێن سنگی: ٣٠ فشار ل ناڤەراستا سنگی — کویراهی ٥-٦ سم، لەز ١٠٠-١٢٠ فشار د خولەکێ دا","٥. هەناسە: سەری بەرەڤ پاش ببە و چەناگێ بلند بکە، دفنێ بگرە و ٢ هەناسێن ١ چرکەیی بدە؛ ئەگەر ڕاهێنان نەدیتبی، تەنێ فشارێن سنگی بکە","٦. بەردەوامی (٣٠:٢): هەتا تیمێ ئەمبوولانسێ (١٢٢) دگەهیت","٧. AED: ئەگەر هەبوو، هەلکە، پەدان ل سەر سنگێ ڕویس دانە و گوهداریا فەرمانێن دەنگی بکە"]},{heading:"٢. ڕاوەستاندنا خوینبەربوونێ",body:"خوینبەربوونا گران دشێت ب لەز ببیتە ئەگەرێ مرنێ:",points:["فشارا ڕاستەوخوە: پارچەکێ پاقژ ل سەر برینێ دانە و ب هێز و بێ ڕاوەستان فشار بدە؛ ئەگەر قوماش ب خوینێ تژی بوو، لانەبە — ئێکێ دی ل سەر دانە","تژیکرنا برینێ (Wound Packing): ئەگەر برین کویر بوو (وەکی ل ڕان، بن مل یان ستۆیێ)، گازێ پاقژ بخە ناڤ برینێ و ب هێز فشار بدە","تۆرنیکێت (Tourniquet): بۆ خوینبەربوونا مەترسیدار ژ دەست یان لنگی ب زوویی بکاربینە، ٥-٧ سم ل سەر برینێ؛ دەمێ دانانێ بنڤیسە و چ جاران سست نەکە","تشتێ چەقی: ئەگەر ئاسن یان شیشە ل ناڤ برینێ بوو — دەرنەئینە! ل دۆر وی جیگیر بکە و گازی ١٢٢ بکە"]},{heading:"٣. چارەسەریا سووتنێ",body:"سووتن ل فەرمانگەهان ژ گەرمی، ماددێن کیمیایی و کارەبایێ چێدبیت:",points:["سووتنا گەرمیێ: ٢٠ خولەک ئاڤا فێنک یا ڕەوان (نە سەهۆل!) بەردە سەر سووتنێ","سووتنا کیمیایی: ٢٠ خولەک ب گەلەک ئاڤا ڕەوان بشۆ","سووتنا کارەبایێ: ئێکەم کارەبایێ ببڕە! پاشان وەکی سووتنا گەرمیێ سار بکە و گازی ١٢٢ بکە","بلقێن سووتنێ نەتەقینە؛ دوهن، مەرهەم یان مەعجوونا ددانان بکارنەئینە"]},{heading:"٤. شکەستن و برینێن ستوونا پشتێ",body:"ل دەمێ کەفتنێ:",points:["جیگیرکرن (Splinting): ئەندامێ بریندار نەلڤینە — ب دارەکێ یان کارتۆنەکێ جیگیر بکە","پاراستنا ستوونا پشتێ: ئەگەر کەسەک ژ بلنداهیێ کەفت، نەلڤینە — بێ لڤین بهێلە و گازی ١٢٢ بکە. تەنێ ئەگەر جه مەترسیدار بیت (ئاگر، ترافیک، هەرفتن، غاز، بلندبوونا ئاڤێ) وی بلڤینە، و سەر، ستۆ و پشتا وی ل سەر ئێک هێلێ بهێلە؛ ئەگەر پێدڤی ب CPR هەبیت، وی ل سەر پشتێ ل سەر ڕووبەرەکێ ڕەق درێژ بکە. وی ل سەر تەنشتێ (Recovery Position) دانەنە","سارکرن: سەهۆلێ د پارچە قوماشەکێ دا بپێچە و ل سەر جهێ ئێشانێ دانە (نە ڕاستەوخوە ل سەر پێستی)"]},{heading:"٥. شۆکا کارەبایێ",body:"کارەبا دشێت دلی ڕاوەستینیت:",points:["ئێکسەر کارەبایێ ببڕە! هەتا کارەبا نەهێتە بڕین دەست ل بریندار نەدە","ئەگەر نەشیای کارەبایێ ببڕی و کارەبا یا ئاسایی یا ئاڤاهیێ بیت (ڤۆلتاژا نزم): ب دارەکێ هشک یان پلاستیکی وایەری ژ وی دویر بێخە؛ ل ڤۆلتاژا بلند دویر بمینە و گازی ١١٥ بکە","هەمی کەسێن کارەبا لێدای دڤێت بچنە نەخۆشخانێ — گازی ١٢٢ بکە؛ ئەگەر هەناسە نەدا، CPR دەستپێبکە"]}],media:[{kind:"video",src:"media/videos/gov_cpr.mp4",title:"CPR و هەوارهاتنا ئێکێ",description:"ڕاهێنانا CPR بۆ فەرمانبەران"}],quiz:[{question:"د CPR دا، چەند فشارێن سنگی د خولەکێ دا دڤێت بن؟",options:[{text:"٥٠-٧٠",correct:!1},{text:"٨٠-٩٠",correct:!1},{text:"١٠٠-١٢٠",correct:!0},{text:"١٥٠+",correct:!1}],explanation:"دڤێت ١٠٠-١٢٠ فشار د خولەکێ دا بن (AHA 2025)."},{question:"ئەگەر تشتەکێ تیژ ل ناڤ برینێ بوو، چ دکەی؟",options:[{text:"دەردئینم",correct:!1},{text:"ل جهێ خوە دهێلم و گازی ١٢٢ دکەم",correct:!0},{text:"دەستێ خوە لادبەم و چ ناکەم",correct:!1},{text:"ب ئاڤێ دشۆم",correct:!1}],explanation:"دەرئینانا تشتی دێ خوینبەربوونێ زێدەتر کەت؛ ل دۆر وی جیگیر بکە و گازی ١٢٢ بکە."},{question:"ئەگەر کارەبا ل کەسەکی دابیت، ئێکەم کار چییە؟",options:[{text:"دەستێ وی دگرم",correct:!1},{text:"CPR دکەم",correct:!1},{text:"کارەبایێ دبڕم",correct:!0},{text:"ئاڤێ دڕێژمە سەر",correct:!1}],explanation:"ئێکەم جار دڤێت کارەبا بهێتە بڕین، دا تو ب خوە نەبییە قوربانی."}]},{id:17,code:"GOV-117",icon:"FlameKindling",accent:"#dc2626",title:"پۆلینکرنا جۆرێن ئاگری",subtitle:"Fire Classification — NFPA 10 / BS EN 2",summary:"پۆلینکرنا نێڤدەولەتی یا جۆرێن ئاگری و هەلبژارتنا تەمرینکا گونجای",blocks:[{body:"پۆلینکرنا ئاگری بنەمایێ کارێ بەرگرییا شارستانی یە. NFPA 10 (ستانداردا ئەمریکی) و EN 2 (ستانداردا ئەوروپی) دوو سیستەمێن سەرەکی نە، و دڤێت هەمی جاران بێژین کیژ سیستەم مەبەستە. پۆلێن ئاگری ل ڤێرێ ب پیتێن NFPA 10 هاتینە نڤیسین وەک ژێدەرێ پرۆژەی؛ سیستەمێ فەرمی یێ دهۆکێ هێشتا نەهاتییە پشتڕاستکرن. بەرامبەرێن EN 2: NFPA A = EN A؛ NFPA B (شلەمەنی) = EN B؛ NFPA B (غاز) = EN C؛ NFPA C (ئامێرێن کارەبایێ یێن کارەبا تێدا) چو پۆل د EN دا نینە؛ NFPA D = EN D؛ NFPA K = EN F. هەلبژارتنا تەمرینکا خەلەت دشێت ئاگری مەزنتر بکەت یان ببیتە ئەگەرێ برینداربوونێ. ئەڤ وانە هەر پۆلەکێ ل دویڤ ستانداردێن نێڤدەولەتی ڕوون دکەت."},{heading:"١. پۆلا A — ماددێن ڕەق (Solid Combustibles)",body:"ماددێن ڕەق یێن ئۆرگانیک کو خۆلی ل دویڤ خوە دهێلن:",points:["سووتەمەنی: دار، کاغەز، قوماش، پلاستیک، لاستیک، زبل","پلەیا گرتنا خوەبەخوە: کاغەز نێزیکی ٢١٨-٢٤٦°C","تایبەتمەندی: خۆلی و ڕەژی ل دویڤ خوە دهێلیت و ئاگر دشێت ل کویراهیا ماددێ بمینیت","تەمرینک: ئاڤ، تۆزا ABC، کەف — لایبلێ (Label) و نیشانێن پۆلێ بخوینە (ڕەنگ نە پۆلا ئاگری یە)","ل فەرمانگەهان: پترییا ماددێن سووتەمەنی کاغەز، فایل و کەل و پەلێن ژوورێ نە","ستاندارد: NFPA 10، EN 2","ڕاهێنان: تەمرینکێ تەنێ بکار بینە ئەگەر ئەڤە هەمی دروست بن: ئاگر بچووک و تازە دەستپێکری بیت، تەمرینک گونجای بیت، ڕێکا دەرکەفتنێ ل پشت تە بیت، ئاگەهداری هاتبیتە دان و گازی ١١٥ هاتبیتە کرن، تو ڕاهێنان دیتی بی، و چو دوکێل یان گەرمی ڕێکا تە نەگریت. پاشی ڕێکارا PASS: ژ وێ دویراتیێ دەستپێبکە یا ل سەر لایبلێ تەمرینکێ هاتی و سەرێ لوولەیێ ئاراستەی بنێ ئاگری بکە؛ ئەگەر ئاگر ئێکسەر ڤەنەمری، دەرکەڤە و دەرگەهی بگرە"]},{heading:"٢. پۆلا B — شلەمەنیێن سووتەمەنی (Flammable Liquids)",body:"شلەمەنیێن کو ل گەرمیا ئاسایی هەلمێن سووتەمەنی چێدکەن (ل NFPA غازێن سووتەمەنی ژی تێدانە):",points:["سووتەمەنی: بەنزین، گازۆیل (Diesel)، نەفتا سپی، ئەلکهول، تینەر، بۆیاخ","خالا هەلبوونێ (Flash Point)، ل دویڤ جۆرێ سووتەمەنیێ: بەنزین نێزیکی −٤٣°C، گازۆیل نێزیکی ٥٢-٩٦°C","تایبەتمەندی: هەلما شلەمەنیێ دسوژیت، نە شلەمەنی ب خوە","تەمرینک بۆ شلەمەنیان: کەف، CO₂ یان تۆزا ABC؛ بۆ ئەلکهولێ و شلەمەنیێن جەمسەری (Polar Solvents) یێن دی: CO₂، تۆزا ABC یان کەفا بەرگرێ ئەلکهولێ (AR Foam)، چونکی کەفا ئاسایی ل سەر وان تێک دچیت. ئاگرێ غازێ (غازا LPG یان غازا سرۆشتی): گرنگترین تشت ڕاوەستاندنا غازێ یە؛ کەسەکێ شیاو کێلۆنا غازێ دگریت تەنێ ئەگەر گەهشتن بۆ وێ سەلامەت بیت. ئەگەر غاز ب سەلامەتی نەهێتە ڕاوەستاندن، ئاگرێ غازێ ڤەنەمرینە: غازا نەسووتی کۆم دبیت و دشێت بتەقیت. ئەگەر سەلامەت نەبوو، هەمیان دەربێخە، ئاگەهداریێ بدە و گازی ١١٥ بکە. کەف نە بژارا گشتی یە بۆ ئاگرێن غازێ","ئاڤێ ب لوولەیێ ل سەر شلەمەنیا سووتی نەڕێژە: شلەمەنیا سووتی دپژقینیت و بەلاڤ دکەت (Slop-over / Boil-over). BLEVE تشتەکێ دی یە: تەقینا دەفرەکا ژێر فشارێ یە پشتی گەرمبوونێ، و سارکرنا دەفرێ ب ئاڤێ ژ دویر دشێت هاریکار بیت بۆ ڕێگرتنێ لێ؛ ئەڤە کارێ تیمێ ١١٥ یە، و هەمی کەسێن دی جهی چۆل دکەن","ل فەرمانگەهان: کۆگەهێن سووتەمەنیا جنێراتۆران و ترومبێلێن خزمەتگوزاریێ","ستاندارد: NFPA 30 (Flammable and Combustible Liquids Code)","ڕێکار: ئۆکسجینێ ببڕە (خەندقاندن / Smothering)، نە تەنێ سارکرن"]},{heading:"٣. پۆلا C ل NFPA — ئامێرێن کارەبایێ یێن کارەبا تێدا (Energized Electrical)",body:"ئاگرێن ل ئامێرێن کارەبایێ دەمێ کارەبا تێدا هەی:",points:["سووتەمەنی: کۆمپیوتەر، سێرڤەر، پلاک، تابلۆیێن کارەبایێ","گەرمیا قەوسا کارەبایێ (Arc Flash): دگەهیتە نێزیکی ١٩٤٠٠°C (٣٥٠٠٠°F) — نێزیکی ٤ جاران گەرمتر ژ ڕوویێ ڕۆژێ (OSHA)","تەمرینک: CO₂، تۆزا ABC، ماددێن پاقژ (Clean Agent) وەکی FK-5-1-12","ئاڤێ و کەفێ ل سەر ئامێرێن کارەبایێ یێن کارەبا تێدا بکار نەئینە، ئەگەر ل سەر لایبلێ پۆلا C یان نیشانا تاقیکرنا کارەبایێ نەبیت (وەک هندەک تەمرینکێن Water Mist) — مەترسیا شۆکا کارەبایێ یا کوژەر","ئێکەم: ئەگەر گەهشتن بۆ تابلۆیێ سەلامەت بیت و ب نێزیکی ئاگری دا دەرباز نەبی، کارەبایێ ژ تابلۆیێ ببڕە؛ پاشی ئاگری ل دویڤ ماددێ سووتی ڤەمرینە","ستاندارد: NFPA 70E (Electrical Safety in the Workplace)","ل ژوورێن ICT: ماددێن پاقژ باشترن — زیانێ ناگەهیننە ئامێرێن گرانبها","تێبینی: ل EN 2 پۆلا C غازن، نە کارەبا؛ ل ئەوروپا ئاگرێن کارەبایێ پۆلەکا جودا نینن، و پۆلا E (کارەبا) تەنێ ل ئوسترالیا دهێتە بکارئینان"]},{heading:"٤. پۆلا D — کانزایێن سووتەمەنی (Combustible Metals)",body:"کانزایێن سووتەمەنی — ئێک ژ مەترسیدارترین جۆران:",points:["سووتەمەنی: ماگنیسیۆم، تیتانیۆم، سۆدیۆم، پۆتاسیۆم، لیتیۆما کانزایی","گەرمی: ماگنیسیۆم ب گەرمیا نێزیکی ٣١٠٠°C (٥٦١٠°F) دسوژیت","چ جاران ئاڤ نە! ئاڤ + ماگنیسیۆم = هایدرۆجین و تەقین","چ جاران CO₂ نە! ماگنیسیۆم ل ناڤ CO₂ ژی دسوژیت و ئاگر زێدە دبیت","تەنێ: تەمرینکەک یان ماددەیەک یێ کو ناڤێ وی کانزای ل سەر لایبلا وی هاتی (تۆزێن پۆلا D وەک سۆدیۆم کلۆراید یان گرافایت)؛ ماددە ژ کانزایەکێ بۆ یێ دی جودایە (بۆ نموونە، لیتیۆم پێدڤی ب ماددەیەکێ تایبەت ب لیتیۆمێ هەیە). چ جاران تۆزا ئاسایی یان کەف نە. خیزا هشک تەنێ ئەگەر پلانا ئاگری یا جهی یان SDS یا کانزای ناڤێ وێ بینیت و تەمام هشک بیت","ل فەرمانگەهان: تاقیگەهێن کیمیایی و جهێن کارێ کانزایان. باتریێن لیتیۆم-ئایۆن یێن ئاسایی لیتیۆما کانزایی تێدا نینە، و بۆ وان سارکرن ب ئاڤێ دهێتە پێشنیارکرن","ستاندارد: NFPA 484 (Combustible Metals)","ئێکسەر گازی ١١٥ بکە — تیمەکێ تایبەت پێدڤییە"]},{heading:"٥. پۆلا F (EN 2) / پۆلا K (NFPA) — ڕۆنێ مەتبەخێ (Cooking Oils)",body:"ڕۆن و دوهنێ مەتبەخێ — ئێک ژ بەلاڤترین ئاگرێن مەتبەخێ:",points:["سووتەمەنی: ڕۆنێ مەتبەخێ (ڕووەکی و ئاژەلی) و دوهن","پلەیا گرتنا خوەبەخوە: ب گشتی پتر ژ ٣٤٠°C، ل دویڤ جۆرێ ڕۆنی","تەمرینک: ماددێ تەڕ (Wet Chemical) — خوێیێن پۆتاسیۆمێ؛ بۆ ڕۆن و دوهنێ مەتبەخێ هاتییە چێکرن، و گەلەک ژ وان بۆ پۆلا A ژی گونجاینە، لەوا لایبلێ بخوینە و ل دویڤ لایبلێ بکار بینە (ل بەریتانیا پارچەیەکا زەر یا BS 7863 ل سەر هەیە)","چ جاران ئاڤ نە! ئاڤ ل ناڤ ڕۆنێ گەرم ب لەز دبیتە هەلم و ڕۆنێ سووتی ب هێز دپژقینیت (گوپکا ئاگری)","تۆزا ABC بۆ ڕۆنێ مەتبەخێ نە گونجایە — ئاگر دشێت دیسان هەلبیت","ڕێکار: ئەگەر ئاگر بچووک بوو، گەرمیێ ببڕە و قاپاخەکێ یان بەتانیا ئاگری (Fire Blanket) بدە سەر و لانەبە","ل کافتریا فەرمانگەهێ: تەمرینکا Wet Chemical نێزیکی جهێ چێکرنا خوارنێ (NFPA 10: نە پتر ژ ٩ مەتران)","ستاندارد: BS EN 3-7، NFPA 10، NFPA 17A (Wet Chemical Systems)"]},{heading:"٦. هەلبژارتنا تەمرینکا گونجای — خشتەیا بڕیاردانێ",body:"بنەما: ١) ماددێ سووتی، ٢) مەزناهیا ئاگری، ٣) جهـ:",points:["خشتە: A: ئاڤ یان ABC | B شلەمەنی: کەف، CO₂ یان ABC (شلەمەنیێن جەمسەری: کەفا AR، CO₂ یان ABC) | B غاز: ئەگەر سەلامەت بیت پێشی غازێ ڕاوەستینە؛ چ جاران ئاگرێ غازێ ڤەنەمرینە ئەگەر نەشێی غازێ ڕاوەستینی | C: CO₂، Clean Agent یان تۆزا ABC (تۆز زیانێ دگەهینیتە ئامێرێن ئەلیکترۆنی) | D: تەمرینکا D یا کو ناڤێ وی کانزای ل سەر هاتی | F/K: Wet Chemical","مەزناهی: تەمرینکێ تەنێ بۆ ئاگرەکێ بچووک یێ تازە دەستپێکری بکار بینە؛ تەمرینکێ بکار نەئینە ئەگەر ئاگر ژ سەتلەکا زبلی مەزنتر بوو، بەلاڤ دبیت یان دوکێل زێدە دبیت: دەرکەڤە و گازی ١١٥ بکە","جهـ: ژوورێن ICT: Clean Agent یان CO₂ | کۆگەهێن کاغەزی: ئاڤ یان ABC | کافتریا: Wet Chemical","بۆ فەرمانگەهەکا ئاسایی: ABC و CO₂، و Wet Chemical ل مەتبەخێ","دەمێ کارکرنێ: تەمرینکێن بچووک ب لەز ڤالا دبن، گەلەک جاران د چەند چرکەیان دا؛ دەمێ ڤالابوونێ یێ دروست ل سەر لایبلێ هاتییە نڤیسین — بەری دەستپێکرنێ د ناڤ وێ دویراتیێ دا بە یا ل سەر لایبلێ هاتی، و ڕێکا دەرکەفتنێ ل پشت تە بیت","پشکنین و خزمەتگوزاری (NFPA 10 و OSHA؛ یاسایێن دهۆکێ هێشتا نەهاتینە پشتڕاستکرن): پشکنینا ب چاڤ هەیڤانە؛ پشکنین و چاککرن سالانە ژ لایێ شارەزایەکێ تەکنیکی ڤە؛ تژیکرنەڤە پشتی هەر بکارئینانەکێ؛ تۆزا هشک یا فشار تێدا: هەر ٦ سالان ڤالاکرن و پشکنینا ناڤخوەیی؛ تاقیکرنا فشارێ (Hydrostatic): هەر ٥ سالان بۆ ئاڤ، کەف، CO₂، Wet Chemical و تۆزا هشک یا لەشێ وێ ژ پۆلایێ ژەنگنەگر (Stainless Steel)، هەر ١٢ سالان بۆ تۆزا هشک یا فشار تێدا یا لەشێ وێ ژ ئاسنێ نەرم، مسێ زەرد یێ لحیمکری یان ئەلەمنیۆمێ"]},{heading:"٧. قۆناغێن گەشەکرنا ئاگری (Stages of Fire)",body:"هەر ئاگرەک ب ٤ قۆناغان دا دبۆریت:",points:["١. دەستپێک (Incipient): دوکێلا کێم و ئاگرێ بچووک","٢. گەشەکرن (Growth): گەرمی زێدە دبیت و ئاگر بەلاڤ دبیت","٣. گەشەکرنا تەمام (Fully Developed): هەمی ماددێن ژوورێ دسوژن و گەرمی دشێت ژ ١٠٠٠°C دەرباس ببیت","٤. کێمبوون (Decay): سووتەمەنی کێم دبیت، لێ مەترسیا Backdraft هەیە","Flashover د ناڤبەرا قۆناغێن ٢ و ٣ دا: دەمێ گەرمیا چینا سەری یا گازان دگەهیتە نێزیکی ٥٠٠-٦٠٠°C، هەمی ماددێن ژوورێ ب لەز ئاگر دگرن","Backdraft: ڤەکرنا دەرگەهی ل ژوورەکا ئاگر تێدا و ئۆکسجین کێم، ئۆکسجینێ دگەهینیتێ و تەقینەکا ئاگری چێدبیت","بەرسڤا فەرمانبەری: تەنێ ل قۆناغا ١ (Incipient) ڤەمراندنا ئاگری سەلامەتە"]}],media:[{kind:"video",src:"media/videos/gov_fire_classes.mp4",title:"پۆلینکرنا جۆرێن ئاگری",description:"نیشاندانا پۆلێن ئاگری ل دویڤ NFPA و EN 2"},{kind:"image",src:"media/images/gov_fire_decision.png",title:"خشتەیا بڕیاردانێ (Decision Matrix)",description:"هەلبژارتنا تەمرینکا گونجای"}],quiz:[{question:"ئاگرێ کۆمپیوتەری (پۆلا C ل NFPA) ب کیژ تەمرینکێ دهێتە ڤەمراندن؟",options:[{text:"ئاڤ",correct:!1},{text:"CO₂ یان Clean Agent",correct:!0},{text:"کەف",correct:!1},{text:"تەمرینکا D",correct:!1}],explanation:"CO₂ یان Clean Agent — چ پاشماوە ناهێلن. تۆزا ABC ژی کار دکەت لێ زیانێ دگەهینیتە ئامێرێن ئەلیکترۆنی. ئاڤ و کەفا ئاسایی کارەبایێ دگوهێزن و دشێن شۆکێ چێبکەن."},{question:"پۆلا D چییە؟",options:[{text:"شلەمەنی",correct:!1},{text:"دار و کاغەز",correct:!1},{text:"کانزایێن سووتەمەنی",correct:!0},{text:"غاز",correct:!1}],explanation:"پۆلا D = کانزایێن سووتەمەنی (ماگنیسیۆم، تیتانیۆم...). تەنێ تەمرینکەک یان ماددەیەک یێ کو ناڤێ وی کانزای ل سەر لایبلا وی هاتی؛ خیزا هشک تەنێ ئەگەر پلانا ئاگری یا جهی یان SDS یا کانزای ناڤێ وێ بینیت و تەمام هشک بیت."},{question:"بۆچی ئاڤ ل سەر ئاگرێ ڕۆنێ مەتبەخێ نابیت؟",options:[{text:"کار ناکەت",correct:!1},{text:"ئاڤ دبیتە هەلم و ڕۆنێ سووتی ب هێز دپژقینیت",correct:!0},{text:"گەلەک گرانە",correct:!1},{text:"ڕۆن چ جاران ئاگر ناگریت",correct:!1}],explanation:"ڕۆنێ گەلەک گەرم ئاڤێ ب لەز دکەتە هەلم؛ هەلم ڕۆنێ سووتی دپژقینیت و گوپکەکا ئاگری چێدکەت."},{question:"NFPA 10 ستانداردا چ یە؟",options:[{text:"پۆلینکرنا کارمەندان",correct:!1},{text:"تەمرینکێن دەستی (Portable Fire Extinguishers)",correct:!0},{text:"سیستەمێن ڕشاندنا ئاڤێ (Sprinkler)",correct:!1},{text:"پاراستنا داتایان",correct:!1}],explanation:"NFPA 10 ستانداردا ئەمریکی یە بۆ تەمرینکێن دەستی: هەلبژارتن، دانان، پشکنین و چاککرن."},{question:"کیژ قۆناغا ئاگری تاکە قۆناغە کو فەرمانبەر ب سەلامەتی بشێت ئاگری ڤەمرینیت؟",options:[{text:"Decay",correct:!1},{text:"Fully Developed",correct:!1},{text:"Incipient",correct:!0},{text:"Flashover",correct:!1}],explanation:"تەنێ ل قۆناغا دەستپێکێ (Incipient) ڤەمراندنا ئاگری ژ لایێ فەرمانبەری ڤە سەلامەتە."},{question:"Flashover ب گشتی دەمێ گەرمیا چینا سەری یا گازان دگەهیتە نێزیکی چ پلەیێ چێدبیت؟",options:[{text:"٢٠٠°C",correct:!1},{text:"٤٠٠°C",correct:!1},{text:"نێزیکی ٥٠٠-٦٠٠°C",correct:!0},{text:"٩٠٠°C",correct:!1}],explanation:"Flashover دەمێ گەرمیا چینا سەری یا گازان دگەهیتە نێزیکی ٥٠٠-٦٠٠°C چێدبیت — هەمی ماددێن ژوورێ ب لەز ئاگر دگرن."}]},{id:18,code:"GOV-118",icon:"FireExtinguisher",accent:"#ea580c",title:"تەمرینکێن ئاگری — جۆر و هەلبژارتن",subtitle:"Fire Extinguisher Types — NFPA 10 + BS EN 3",summary:"شەش جۆرێن سەرەکی یێن تەمرینکێن دەستی ل دویڤ ستانداردێن نێڤدەولەتی و هەلبژارتنا وان بۆ فەرمانگەهان",blocks:[{body:"تەمرینکا ئاگری ل فەرمانگەهان دڤێت ل دویڤ جۆرێ ئاگرێ مومکین بهێتە هەلبژارتن. بۆ پترییا فەرمانگەهان، تۆزا ABC و CO₂ پێکڤە بنەمانە، و Wet Chemical ل مەتبەخێ. ئەڤ وانە شەش جۆرێن سەرەکی، ڕەنگێن وان، قەبارە، ڕێکارا PASS و خشتەیا پشکنینێ ڕوون دکەت. پۆلێن ئاگری ل ڤێرێ ب پیتێن NFPA 10 هاتینە نڤیسین وەک ژێدەرێ پرۆژەی؛ سیستەمێ فەرمی یێ دهۆکێ هێشتا نەهاتییە پشتڕاستکرن. بەرامبەرێن EN 2: NFPA A = EN A؛ NFPA B (شلەمەنی) = EN B؛ NFPA B (غاز) = EN C؛ NFPA C (ئامێرێن کارەبایێ یێن کارەبا تێدا) چو پۆل د EN دا نینە؛ NFPA D = EN D؛ NFPA K = EN F. ڕەنگ نە پۆلا ئاگری یە: ڕەنگێن ل خوارێ ڕێکارا بەریتانیا نە (لەشێ سوور ل دویڤ BS EN 3 و پارچەیەکا ڕەنگکری ل دویڤ BS 7863)؛ ڕەنگێن د دهۆکێ دا هێشتا نەهاتینە پشتڕاستکرن، لەوا هەمیشە لایبلێ (Label) و نیشانێن پۆلێ بخوینە."},{heading:"١. تەمرینکا ئاڤێ — Water (پۆلا A)",body:"بەلاڤترین تەمرینک بۆ پۆلا A — ماددێن ڕەق:",points:["ڕەنگ ل بەریتانیا (BS EN 3): هەمی سوور، بێ پارچە","پۆل: تەنێ A (دار، کاغەز، قوماش، پلاستیک)","چەوانیا کارکرنێ: ئاگری سار دکەت و گەرمیێ کێم دکەت","قەبارێن بەلاڤ: ٦ و ٩ لیتر","دویراتی: ژ وێ دویراتیێ دەستپێبکە یا ل سەر لایبلێ تەمرینکێ هاتی، ڕێکا دەرکەفتنێ ل پشت تە بیت، و تەنێ دەمێ ئاگر بچووک دبیت نێزیکتر ببە","چ جاران بۆ کارەبایێ (شۆک)، شلەمەنیان و ڕۆنێ مەتبەخێ (ئاگری بەلاڤ دکەت) بکارنەئینە","ل فەرمانگەهێ: کۆریدۆر و ژوورێن ئەرشیڤێ","بهایێ وێ کێمە، لێ تەنێ بۆ پۆلا A گونجایە","پشکنین: پشکنینا ب چاڤ هەیڤانە (پێڤەرێ فشارێ ئەگەر هەبیت، مێخا سەلامەتیێ و مۆر) و پشکنین و چاککرنا سالانە ژ لایێ کەسەکێ شارەزا ڤە"]},{heading:"٢. تەمرینکا کەفێ — Foam (پۆلێن A و B)",body:"کەفا AFFF (Aqueous Film-Forming Foam):",points:["ڕەنگ ل بەریتانیا (BS EN 3 / BS 7863): سوور ب پارچەیەکا کرێمی","پۆل: A و B (شلەمەنیێن سووتەمەنی) — نە بۆ ئەلکهولێ و شلەمەنیێن جەمسەری (Polar Solvents) یێن دی ئەگەر کەفا بەرگرێ ئەلکهولێ (AR Foam) نەبیت، و نە بژارا گشتی یە بۆ ئاگرێن غازێ","چەوانیا کارکرنێ: کەف چینەکێ ل سەر شلەمەنیێ چێدکەت، ئۆکسجینێ دبڕیت و سار دکەت","قەبارێن بەلاڤ: ٦ و ٩ لیتر","دویراتی: ژ وێ دویراتیێ دەستپێبکە یا ل سەر لایبلێ هاتی و تەنێ دەمێ ئاگر بچووک دبیت نێزیکتر ببە","گونجای بۆ: کۆگەهێن سووتەمەنیێ و جهێن جنێراتۆران","بۆ ئامێرێن کارەبایێ یێن کارەبا تێدا بکارنەئینە — وەکی ئاڤێ کارەبایێ دگوهێزیت","ل فەرمانگەهێ: پارکینگا ترومبێلان و کۆگەها گازۆیلێ","AFFF ماددێن PFAS تێدانە کو زیانێ دگەهیننە ژینگەه و ساخلەمیێ؛ کەفا بێ فلۆر (Fluorine-Free Foam) جهگرێ نوو یە"]},{heading:"٣. تەمرینکا CO₂ — Carbon Dioxide (پۆلا B و ئاگرێن کارەبایێ)",body:"باشترین بۆ ئامێرێن کارەبایێ و شلەمەنیان:",points:["ڕەنگ ل بەریتانیا (BS EN 3 / BS 7863): سوور ب پارچەیەکا ڕەش","پۆل: B و ئامێرێن کارەبایێ یێن کارەبا تێدا (پۆلێن B و C ل NFPA؛ ل EN 2 پۆلا C غازە و CO₂ بۆ ئاگرێن غازێ نەهاتییە پەسەندکرن)","چەوانیا کارکرنێ: غازا CO₂ ئۆکسجینێ ل دۆر ئاگری لادەت (خەندقاندن)","قەبارێن بەلاڤ: ٢ و ٥ کغ","دویراتی: مەودایێ CO₂ کورتە؛ ژ وێ دویراتیێ دەستپێبکە یا ل سەر لایبلێ هاتی و تەنێ دەمێ ئاگر بچووک دبیت نێزیکتر ببە","گونجای بۆ: ژوورێن ICT، تابلۆیێن کارەبایێ، ژوورا سێرڤەران (Server Room)","چ پاشماوە ناهێلیت و زیانێ ناگەهینیتە ئامێرێن گرانبها؛ لێ بۆ ئاگرێن کویر یێن پۆلا A باش نینە","مەترسی: ل ژوورێن گرتی ئۆکسجینێ کێم دکەت — پشتی بکارئینانێ ژوورێ چۆل بکە و هەوایێ نوو بکە","قیفا وێ گەلەک سار دبیت (نێزیکی −٧٨°C) — دەست ل قیفێ نەدە، تەنێ دەسکێ بگرە","ل فەرمانگەهێ: بەشێ ICT، ژوورا سێرڤەران و نێزیکی تابلۆیێن کارەبایێ"]},{heading:"٤. تەمرینکا تۆزا هشک ABC — Dry Chemical Powder",body:"بەلاڤترین تەمرینک — بۆ پۆلێن A، B و C، نە بۆ D و K/F:",points:["ڕەنگ ل بەریتانیا (BS EN 3 / BS 7863): سوور ب پارچەیەکا شین","پۆل: A، B و C — نە D (کانزا) و نە K/F (ڕۆنێ مەتبەخێ)","ماددە: فۆسفاتا ئەمۆنیۆمێ (Monoammonium Phosphate)","چەوانیا کارکرنێ: تۆز کارلێکا کیمیایی یا ئاگری ڕادوەستینیت","قەبارێن بەلاڤ: ١، ٢، ٦ و ٩ کغ","دویراتی: ژ وێ دویراتیێ دەستپێبکە یا ل سەر لایبلێ هاتی و تەنێ دەمێ ئاگر بچووک دبیت نێزیکتر ببە","گونجای بۆ: کۆریدۆر، گاراج و کۆگەهـ — نە بۆ ڕۆنێ مەتبەخێ","تۆز ل ژوورێ بەلاڤ دبیت، دیتنێ کێم دکەت و پاقژکرنا وێ زەحمەتە","تۆز زیانێ دگەهینیتە ئامێرێن ئەلیکترۆنی — بۆ کۆمپیوتەر و ICT، CO₂ باشترە","ل فەرمانگەهێ: کۆریدۆر، گاراج و نێزیکی دەرکەفتنان","بهایێ وێ کێمە و ب گشتی ل فەرمانگەهان دهێتە دانان"]},{heading:"٥. تەمرینکا ماددێ تەڕ — Wet Chemical (پۆلا F/K) — مەتبەخ",body:"تایبەتە بۆ ڕۆن و دوهنێ گەرمێ مەتبەخێ:",points:["ڕەنگ ل بەریتانیا (BS EN 3 / BS 7863): سوور ب پارچەیەکا زەر","پۆل: K (NFPA) / F (EN 2) — ڕۆنێ مەتبەخێ","ماددە: خوێیێن پۆتاسیۆمێ (Potassium Acetate یان Potassium Citrate)","چەوانیا کارکرنێ: ڕۆنی دکەتە چینەکا وەکی سابوونێ (Saponification) کو ڕۆنی سار دکەت و ئۆکسجینێ دبڕیت","قەبارێن بەلاڤ: ٢ و ٦ لیتر","ل دویڤ لایبلێ بکار بینە: ب هێواشی و ب لوولەیا درێژ ل سەر ڕۆنی بڕێژە دا ڕۆن نەپژقیت","بۆ ڕۆن و دوهنێ مەتبەخێ هاتییە چێکرن (NFPA K / EN F)؛ گەلەک ژ وان بۆ پۆلا A ژی گونجاینە، لەوا لایبلێ بخوینە. نە بۆ گازۆیل و نەفتێ (پۆلا B)","چ جاران ئاڤ ل سەر ڕۆنێ گەرم نە — ئاڤ دبیتە هەلم و ڕۆنێ سووتی دپژقینیت!","ل فەرمانگەهێ: کافتریا و مەتبەخ","بەری بکارئینانێ، ئەگەر سەلامەت بوو، غاز یان کارەبایا ئامێرێ چێکرنا خوارنێ ببڕە"]},{heading:"٦. ماددێن پاقژ — Clean Agent (FK-5-1-12 / HFC-227ea)",body:"بۆ ICT و ئامێرێن گرانبها:",points:["ڕەنگ: لەشێ سوور و ناڤێ ماددێ ل سەر نڤیسیە (ل هندەک وەلاتان نیشانەکا کەسک)","پۆل: ل دویڤ مۆدێلی دگوهۆڕیت؛ لایبلێ بخوینە","ماددە: FK-5-1-12 (ناڤێ بازرگانی Novec 1230) یان HFC-227ea","چەوانیا کارکرنێ: غازەکا پاقژ — چ پاشماوە ناهێلیت و زیانێ ناگەهینیتە ئامێران","سیستەمێن جیگیر یێن ماددێن پاقژ (NFPA 2001)، کو نە تەمرینکێن دەستی نە، د ١٠ چرکەیان یان کێمتر دا ڤالا دبن","گونجای بۆ: ژوورا سێرڤەران (Server Room)، ناڤەندا داتایان (Data Center)، ئەرشیڤ","تەمرینکا دەستی یا ماددێن پاقژ: پۆل و کێمترین قەبارەیا ژوورێ ل سەر لایبلێ نە؛ پشتی بکارئینانێ ژوورێ بهێلە. سیستەمێن جیگیر: ب ڕێژێن دیزاینێ ماددە بۆ مرۆڤان سەلامەتە، لێ ژبەر دوکێل و ماددێن ژ ئاگری چێدبن، ژوور دڤێت بهێتە چۆلکرن","زیانێ ناگەهینیتە چینا ئۆزۆنێ و جهێ Halon 1301 گرتییە","گرانە؛ ل ژوورێن سێرڤەران گەلەک جاران وەکی سیستەمەکێ جیگیر یێ تژیکرنا ژوورێ (Total Flooding) دهێتە دانان، کو ژ تەمرینکێن دەستی جودایە","ل فەرمانگەهێ: تەنێ ل جهێن هەستیار — ژوورا سێرڤەران و ناڤەندا کارێن تەنگاڤیێ (EOC)","ستاندارد: NFPA 2001 (Clean Agent Fire Extinguishing Systems)"]},{heading:"٧. PASS — ڕێکارا بکارئینانێ",body:`بەری تو تەمرینکێ بکار بینی (دڤێت هەمی بەرسڤ «بەلێ» بن):
• ئاگر بچووکە و تازە دەستپێکرییە، وەک ئاگرەکێ د سەتلەکا زبلی یان تاوەیەکێ دا.
• تەمرینک یا گونجایە بۆ ڤی جۆرێ ئاگری.
• ڕێکا دەرکەفتنێ ل پشت تەیە و ئاگر د ناڤبەرا تە و دەرکەفتنێ دا نینە.
• ئاگەهداری هاتییە دان: کەسێن دی ئاگەهدار بوون و گازی ١١٥ هاتییە کرن.
• تو بۆ بکارئینانا تەمرینکێ ڕاهێنان دیتی یی.
• چو دوکێل یان گەرمی ڕێکا دەرکەفتنا تە ناگریت.
• ئەگەر ئاگر ئێکسەر ڤەنەمری، ڕاوەستە، دەرکەڤە و دەرگەهی ل پشت خوە بگرە.

ڕێکارا PASS ڕێکارا گشتی یە بۆ پترییا تەمرینکێن دەستی. تەمرینکێن Class D، ماددێ تەڕ (Wet Chemical)، ماددێن پاقژ (Clean Agent) و یێن ل سەر چەرخان: ل دویڤ لایبلێ و ڕێنمایێن کۆمپانیا دروستکەر بکار بینە. هەنگاڤ ب هەنگاڤ:`,points:["P = Pull (بکێشە): مێخا سەلامەتیێ بکێشە و مۆرێ بشکێنە","A = Aim (ئاراستە بکە): سەرێ لوولەیێ بەرەڤ بنێ ئاگری، نە سەرێ ئاگری — ژ وێ دویراتیێ دەستپێبکە یا ل سەر لایبلێ تەمرینکێ هاتی و تەنێ دەمێ ئاگر بچووک دبیت نێزیکتر ببە","S = Squeeze (بگڤاشە): دەسکێ ب هێز و ب بەردەوامی بگڤاشە","S = Sweep (بلڤینە): ژ لایەکی بۆ لایێ دی، ب هێواشی، هەتا ئاگر ڤەدمریت","تەمرینکێن بچووک ب لەز ڤالا دبن، گەلەک جاران د چەند چرکەیان دا؛ دەمێ ڤالابوونێ یێ دروست ل سەر لایبلێ هاتییە نڤیسین — ئامادە بە","جهێ ڕاوەستانێ: ڕێکا دەرکەفتنێ (دەرگەهـ) ل پشت تە بیت","پشتی ڤەمراندنێ چاڤدێریا جهی بکە؛ ئەگەر ئاگر دیسان هەلبوو، دیسان PASS بکە یان دەرکەڤە","ئەگەر ئاگر ئێکسەر ڤەنەمری یان تەمرینک ڤالا بوو: ئێکسەر دەرکەڤە، دەرگەهی ل پشت خوە بگرە و پشتڕاست ببە کو گازی ١١٥ هاتییە کرن"]},{heading:"٨. هەلبژارتنا گونجای بۆ فەرمانگەهان",body:"پلانا تەمرینکێن فەرمانگەهێ:",points:["نموونە بۆ فەرمانگەهەکێ: ABC ل کۆریدۆران، CO₂ نێزیکی ئامێرێن کارەبایێ و ICT، و Wet Chemical ل مەتبەخێ (ئەگەر هەبیت)","ل دویڤ NFPA 10، ل جهەکێ مەترسیا کێم (Light Hazard) هەر یەکەیەکا A (A Unit) ڕووبەرەکێ هەتا ٣٠٠٠ پێ² (نێزیکی ٢٧٩ م²) دپارێزیت، لەوا تەمرینکەکا 2-A هەتا نێزیکی ٥٥٧ م² (٦٠٠٠ پێ²) دپارێزیت؛ چو تەمرینکەک نابیت ژ نێزیکی ١٠٤٥ م² (١١٢٥٠ پێ²) پتر بپارێزیت، و نابیت چو کەس پێدڤی بیت ژ ٢٣ م (٧٥ پێ) پتر بچیت دا بگەهیتە تەمرینکەکێ. کۆدا بەریتانی BS 5306-8 پێشنیار دکەت کو لایێ کێم ٢ تەمرینک ل هەر قاتەکی هەبن (ژبلی قاتێن گەلەک بچووک). پێدڤیاتیا فەرمانگەهێن دهۆکێ ژ لایێ ڕێڤەبەرییا بەرگرییا شارستانی ڤە دهێتە دانان و هێشتا نەهاتییە پشتڕاستکرن","دویراتیا گەهشتنێ (Travel Distance): نە پتر ژ ٢٣ مەتران بۆ پۆلا A، ٩ یان ١٥ مەتر بۆ پۆلا B (ل دویڤ پلەیا تەمرینکێ)، ٩ مەتر بۆ پۆلا K (NFPA 10)","ل سەر دیواری و نێزیکی دەرگەهان؛ سەرێ تەمرینکێ نە بلندتر ژ ١.٥ مەتران ژ ئەردی (بۆ تەمرینکێن هەتا ١٨ کغ — NFPA 10)","نیشانا تەمرینکێ (ISO 7010 F001) ل جهەکێ بلند دابنێ دا ژ دویر ڤە بهێتە دیتن","پشکنینا ب چاڤ (هەیڤانە، ژ لایێ کارمەندەکێ دیارکری ڤە): ل جهێ خوە بیت، دیار بیت و گەهشتن پێ ب ساناهی بیت؛ مێخا سەلامەتیێ و مۆر نەشکەستی بن؛ لایبل ب ساناهی بهێتە خوەندن و بەرەڤ دەرڤە بیت؛ چو زیان یان ژەنگ پێڤە نەبیت و ماددە ژێ دەرنەکەڤیت؛ لوولە و سەرێ لوولەیێ نە گرتی بن؛ ئەگەر پێڤەرێ فشارێ هەبیت، دەرزیکا وی ل ناڤچەیا کەسک بیت. تەمرینکێن CO₂ پێڤەر نینە: ڕاکە دا هەست بکەی کو تژی یە","پشکنین و چاککرن (سالانە، ژ لایێ تەکنیکارەکێ شارەزا ژ کۆمپانیەکا پەسەندکری ڤە)","تژیکرنەڤە (Recharge): پشتی هەر بکارئینانەکێ، هەتا یا کورت ژی، ژ لایێ تەکنیکارەکێ شارەزا ڤە","چاککرنا ٦ سالان: تەمرینکێن تۆزا هشک (ABC) یێن فشار تێدا (Stored Pressure) کو پێدڤی ب تاقیکرنا فشارێ یا ١٢ سالان هەی، هەر ٦ سالان دهێنە ڤالاکرن و پشکنینا ناڤخوەیی بۆ دهێتە کرن (NFPA 10) — ئەڤە گوهۆڕینا تەمرینکێ نینە","تاقیکرنا فشارێ یا لەشێ تەمرینکێ (Hydrostatic Test)، ل دویڤ جۆری: هەر ٥ سالان بۆ ئاڤ، کەف (AFFF)، CO₂، Wet Chemical و تەمرینکێن تۆزا هشک یێن لەشێ وان ژ پۆلایێ ژەنگنەگر (Stainless Steel)؛ هەر ١٢ سالان بۆ تەمرینکێن تۆزا هشک (ABC) یێن فشار تێدا یێن لەشێ وان ژ ئاسنێ نەرم (Mild Steel)، مسێ زەرد یێ لحیمکری (Brazed Brass) یان ئەلەمنیۆمێ. یاسایێن دهۆکێ هێشتا نەهاتینە پشتڕاستکرن","دەرئێخستن ژ خزمەتێ: تەمرینک ژ خزمەتێ دهێتە دەرئێخستن ئەگەر د پشکنینێ یان تاقیکرنێ دا سەرنەکەفت، زیان پێ کەفتبیت، کەڤن بووبیت (Obsolete) یان ژ لایێ کۆمپانیێ ڤە هاتبیتە ڤەگەڕاندن (Recall)، لایبلا وێ نەهێتە خوەندن، یان تەمرینکەکا ئێکجاری (Non-rechargeable) بیت و دەمێ کارکرنێ یێ ل سەر لایبلێ دەرباس بووبیت"]}],media:[{kind:"video",src:"media/videos/gov_ext_pass.mp4",title:"ڕێکارا PASS (PASS Technique)",description:"تاقیکرنا ڕێکارا PASS"},{kind:"image",src:"media/images/gov_ext_chart.png",title:"خشتەیا هەلبژارتنا تەمرینکان (Extinguisher Selection Chart)",description:"هەلبژارتن ل دویڤ پۆلا ئاگری"}],quiz:[{question:"تەمرینکا ABC بۆ کیژ پۆلان گونجایە؟",options:[{text:"تەنێ A",correct:!1},{text:"A + B + C",correct:!0},{text:"تەنێ B + C",correct:!1},{text:"D + K",correct:!1}],explanation:"ABC بۆ پۆلێن A، B و C یە (فۆسفاتا ئەمۆنیۆمێ) — نە بۆ D (کانزا) و نە بۆ K/F (ڕۆنێ مەتبەخێ)."},{question:"بۆ ژوورا سێرڤەران (Server Room)، کیژ تەمرینک گونجایە؟",options:[{text:"تۆزا ABC",correct:!1},{text:"ئاڤ",correct:!1},{text:"Clean Agent (FK-5-1-12)",correct:!0},{text:"کەف",correct:!1}],explanation:"Clean Agent چ پاشماوە ناهێلیت و زیانێ ناگەهینیتە ئامێران."},{question:"P د PASS دا چ دگەهینیت؟",options:[{text:"Push",correct:!1},{text:"Pull",correct:!0},{text:"Point",correct:!1},{text:"Press",correct:!1}],explanation:"P = Pull (مێخا سەلامەتیێ بکێشە)."},{question:"ل دویڤ NFPA 10، دویراتیا گەهشتنێ (Travel Distance) بۆ تەمرینکا پۆلا A نابیت ژ چەند پتر بیت؟",options:[{text:"١٠ مەتر",correct:!1},{text:"٢٣ مەتر",correct:!0},{text:"٥٠ مەتر",correct:!1},{text:"١٠٠ مەتر",correct:!1}],explanation:"NFPA 10: هەتا ٢٣ مەتر (٧٥ پێ) بۆ پۆلا A؛ بۆ پۆلا B ٩ یان ١٥ مەتر ل دویڤ پلەیا تەمرینکێ."},{question:"گەرمیا CO₂ ل دەمێ دەرکەفتنێ ژ تەمرینکێ نێزیکی چەندە؟",options:[{text:"٠°C",correct:!1},{text:"−٧٨°C",correct:!0},{text:"−٣٠°C",correct:!1},{text:"٢٠°C",correct:!1}],explanation:"CO₂ ب گەرمیا نێزیکی −٧٨°C دەردکەڤیت — دەست ل قیفێ نەدە، دا دەستێ تە ژ سەرمایێ نەسوژیت (Frostbite)."},{question:"مەترسیا کەفا AFFF چییە؟",options:[{text:"چ مەترسی نینە",correct:!1},{text:"PFAS — زیانا ژینگەهی",correct:!0},{text:"گەلەک گرانە",correct:!1},{text:"گەلەک سارە",correct:!1}],explanation:"AFFF ماددێن فلۆری (PFAS) تێدانە کو مەترسیێ ل سەر ژینگەهێ چێدکەن؛ کەفا بێ فلۆر جهگرێ نوو یە."}]},{id:19,code:"GOV-119",icon:"HeartHandshake",accent:"#db2777",title:"هەوارهاتنا ئێکێ بۆ فەرمانبەران",subtitle:"Workplace First Aid — Primary Check + CPR + AED + Common Emergencies",summary:"بەرنامەیێ تەمام یێ هەوارهاتنا ئێکێ بۆ کارمەندێن فەرمانگەهان",blocks:[{body:"د تەنگاڤیێ دا، خولەکێن ئێکێ گەلەک گرنگن: ئەگەر دل ڕاوەستیا، زیانا مێشکی پشتی چەند خولەک دەستپێدکەت، و هەر خولەکەکا گیرۆبوونا CPR و شۆکا AED شانسا ڕزگاربوونێ کێم دکەت. ئەڤ وانە پشکنینا ئێکێ، CPR ل فەرمانگەهێ، AED، خەندقین، خوینبەربوون، سووتن و تەنگاڤیێن دی یێن بەلاڤ ڕوون دکەت."},{heading:"١. پشکنینا ئێکێ — مەترسی، بەرسڤ، هەناسە",body:"ڕێکارا ئێکێ پشتی دیتنا کەسەکێ کەفتی یان بێهێز:",points:["مەترسی (Danger): بەری نێزیک ببی، جهی بپشکنە: کارەبا، ئاگر، غاز، هاتوچۆ؟ سەلامەتیا تە ئێکەمە","بەرسڤ (Response): ملێن وی ب هێواشی بلەقینە و ب دەنگەکێ بلند بپرسە: «تو باشی؟»","ئەگەر بەرسڤ نەدا: گازی هاریکاریێ بکە، گازی ١٢٢ بکە (مۆبایلێ ل سەر سپیکەرێ دانە) و کەسەکی بهنێرە دا AED بینیت","هەناسە (Breathing): هەتا ١٠ چرکەیان سەحکە سنگی کا ب دروستی بلند و نزم دبیت یان نە","ئەگەر هەناسە نەدا یان تەنێ هەناسێن نە ئاسایی (Gasping) هەبن: ئەڤە ڕاوەستانا دلی یە — ئێکسەر فشارێن سنگی دەستپێبکە","کەسێن ئاسایی (نە پزیشک) نەبزێ (Pulse) ناپشکنن — دەمی ب پشکنینێ ب هەدەر نەدە","ئەگەر ب دروستی هەناسە ددا و گومانا برینداربوونا ستۆ یان پشتێ نەبیت: ل سەر تەنشتێ دانە (Recovery Position)، چ ب دەڤی نەدەیێ و چاڤدێریا هەناسێ بکە هەتا ئەمبوولانس دگەهیت"]},{heading:"٢. CPR ل فەرمانگەهێ",body:"بۆ کارمەندان (نە پزیشک):",points:["جهێ دەستان: ناڤەراستا سنگی (نیڤا ژێرێ یا هەستیێ سنگی)، دەستەک ل سەر یێ دی","بازوو ڕاست بن و ملێن تە ڕاستەوخوە ل سەر سنگی بن؛ هێزێ ژ کەمبەر و لەشێ خوە بدە","کویراهی: ٥-٦ سم بۆ هەمی مەزنان","لەز: ١٠٠-١٢٠ فشار د خولەکێ دا؛ پشتی هەر فشارەکێ بهێلە سنگ ب تەمامی بزڤڕیت","ڕێژە: ٣٠ فشار + ٢ هەناسە؛ ئەگەر ڕاهێنان نەدیتبی، تەنێ فشارێن سنگی (Hands-Only CPR) بکە","ئەگەر دوو کەس هەبن: هەر ٢ خولەک (٥ خول) جهێ خوە بگوهۆڕن دا هێزا فشاران کێم نەبیت","ڕانەوەستە هەتا: AED دگەهیت و کار دکەت، تیمێ پزیشکی دگەهیت، یان کەس ب ئاشکرایی هشیار دبیت","خەلەتیێن بەلاڤ: کویراهیا کێم، لەزا کێم، ڕاوەستانێن درێژ، و نەهێلانا سنگی بزڤڕیت"]},{heading:"٣. AED — ئامێرێ شۆکا دلی یێ ئۆتۆماتیکی (Automated External Defibrillator)",body:"پێشنیار دهێتە کرن ل هەر ئاڤاهیەکێ حکومی یێ مەزن هەبیت:",points:["جهـ: ل کۆریدۆرەکا گشتی و دیار، دا ب لەز بگەهنێ","نیشان: سندوقێ ب نیشانا AED (ISO 7010 E010) و ب ڕۆناهیەکا دیار","ئارمانج: AED د ماوەیێ نێزیکی ٣ خولەک دا بگەهیتە هەر جهەکێ ئاڤاهیێ","هەنگاڤ: ١) هەلکە، ٢) دوو پەدان ل سەر سنگێ ڕویس دانە، ٣) گوهداریا دەنگی بکە، ٤) ئەگەر داخوازا شۆکێ کر، دوگمێ بگڤاشە","بەری شۆکێ ب دەنگ بێژە «دویر ببن!» — کەس دەست ل کەسی نەدەت","پشکنینا هەیڤانە: باتری و دەمێ بەسەرچوونا پەدان","پشتی شۆکێ: ئێکسەر ٢ خولەک CPR بکە، پاشان AED دیسان شیکاری دکەت","پشتی بکارئینانێ: پەد و باتریێن نوو دابنێ دا ئامێر بۆ جارا دی ئامادە بیت"]},{heading:"٤. خەندقین (Choking)",body:"ئەگەر تشتەک ل قورگێ مرۆڤی گیر بوو:",points:["پشکنین: ئەرێ دشێت باخڤیت، کۆخ بکەت یان هەناسێ بدەت؟","ئەگەر ب هێز کۆخ دکەت: هانبدە کۆخێ بکەت و ل نک بمینە","ئەگەر نەشێت باخڤیت، کۆخ بکەت یان هەناسێ بدەت: گازی ١٢٢ بکە (یان کەسەکێ دی بدە گازیکرن) و ئێکسەر دەستپێبکە","٥ لێدانێن پشتێ: وی بەرەڤ پێش بچەمینە و ب بنێ دەستی ب هێز د ناڤبەرا هەردوو ملان دا لێبدە","٥ فشارێن زکی (Heimlich): ل پشت وی ڕاوەستە، مستێ خوە ل سەر ناڤکێ و گەلەک ل خوار هەستیێ سنگی دانە، ب دەستێ دی بگرە و ب لەز بەرەڤ ژوور و ناڤ فشار بدە","٥ لێدانێن پشتێ و ٥ فشارێن زکی دووبارە بکە هەتا تشت دەردکەڤیت؛ ئەگەر بێهۆش بوو، CPR دەستپێبکە","زارۆکێن ژ ١ سالی کێمتر: ٥ لێدانێن پشتێ (سەر ژ سنگی نزمتر) + ٥ فشارێن سنگی ب بنێ ئێک دەستی؛ چ جاران فشارێن زکی نە","ژنا دووگیان یان کەسێ کو دەستێن تە ل دۆر زکێ وی ناگەهن: فشارێن سنگی (Chest thrusts) ل جهێ فشارێن زکی"]},{heading:"٥. ڕاوەستاندنا خوینبەربوونێ (Stop the Bleed)",body:"سێ ڕێکارێن سەرەکی یێن Stop the Bleed:",points:["١. فشارا ڕاستەوخوە: پارچەکێ پاقژ ل سەر برینێ دانە و ب هەردوو دەستان ب هێز و بێ ڕاوەستان فشار بدە","٢. تژیکرنا برینێ (Wound Packing): ل برینێن کویر (ڕان، بن مل، ستۆ)، گازێ پاقژ بخە ناڤ برینێ و ب هێز فشار بدە","٣. تۆرنیکێت (Tourniquet): بۆ خوینبەربوونا مەترسیدار ژ دەست یان لنگی، ب زوویی؛ ٥-٧ سم ل سەر برینێ، نە ل سەر جومگەیێ","دەمێ دانانا تۆرنیکێتێ بنڤیسە و چ جاران سست نەکە یان ڤەنەکە — تەنێ تیمێ پزیشکی لادبەت","چ جاران تشتێ چەقی ژ برینێ دەرنەئینە (دێ خوینبەربوون زێدەتر بیت)","ئەگەر تشتەک چەقی بوو: قوماشی ل دۆر وی بپێچە دا نەلڤیت و فشارێ ل دۆر وی بدە، نە ل سەر وی","برینا سەری: فشارا هێواش بدە؛ ئەگەر گومانا شکەستنا هەستیێ سەری هەبوو، فشارا ب هێز نەدە","برینا چاڤی: فشار ل سەر چاڤی نەدە — تەنێ ب قوماشەکێ پاقژ ب سستی بپۆشە","ل خوینبەربوونا گران ئێکسەر گازی ١٢٢ بکە؛ ئەگەر قوماش ب خوینێ تژی بوو، لانەبە — ئێکێ دی ل سەر دانە"]},{heading:"٦. سووتن (Burns)",body:"پلێن سووتنێ و ڕووبەرێ لەشی یێ سووتی (TBSA):",points:["پلا ١ (سەرپێستی): تەنێ سووربوون و ئێش — وەکی سووتنا تاڤێ","پلا ٢ (نیڤ-کویر): بلق و ئێشا ب هێز","پلا ٣ (کویر): پێست سپی، قەهوەیی یان ڕەش دبیت؛ دبیت ئێش نەبیت چونکی دەمار سووتینە","ڕێسایا ٩ان (Rule of 9s) بۆ مەزنان: سەر ٩٪، هەر دەستەک ٩٪، هەر لنگەک ١٨٪، سنگ و زک ١٨٪، پشت ١٨٪، ئەندامێن زایەندی ١٪","ئێکسەر ٢٠ خولەک ب ئاڤا فێنک یا ڕەوان سار بکە (نە سەهۆل، نە ئاڤا گەلەک سار)","پاشان ب نایلۆنا خوارنێ (Cling Film) یان قوماشەکێ پاقژ یێ نەنووسێ ب سستی بپۆشە","سووتنا کیمیایی: لایێ کێم ٢٠ خولەک ب ئاڤا ڕەوان بشۆ و پەڕا SDS بپشکنە","سووتنا کارەبایێ: ئێکەم کارەبایێ ببڕە؛ برینەکا چوونێ و برینەکا دەرکەفتنێ هەنە و زیانا ناڤخوەیی دبیت پتر بیت","چ جاران: سەهۆل، دوهن، کرێم یان مەعجوونا ددانان؛ بلقان نەتەقینە و جلێن پێڤە نووسیای ڤەنەکێشە","گازی ١٢٢ بکە ئەگەر: سووتن مەزن یان کویر بیت، ل سەر دێم، دەست، پێ یان ئەندامێن زایەندی بیت، سووتنا کارەبایێ بیت، یان کەسی دوکێل هەلمژیبیت"]},{heading:"٧. تەنگاڤیێن دی یێن بەلاڤ",body:"ڕەوشێن بەلاڤ ل فەرمانگەهان:",points:["بێهۆشبوونا کورت (Fainting): ل سەر پشتێ دانە، ئەگەر بریندار نەبوو لنگێن وی نێزیکی ٣٠ سم بلند بکە و هەوایێ نوو بێخە ژوورێ","تەنگاڤیا شەکرێ (Diabetic Emergency): ئەگەر هشیار بوو و بشێت قوت بدەت، شەکر یان ڤەخوارنەکا شرین بدەیێ. ئەگەر بێهۆش بوو: چ ب دەڤی نەدەیێ، ل سەر تەنشتێ دانە و گازی ١٢٢ بکە. گلوکاگۆن (Glucagon) تەنێ ئەگەر پزیشکی بۆ وی نڤیسیبیت و تو ل سەر ڕاهێنان دیتبی","تیرسا ژنشکەکێ (Panic Attack): ب ئارامی دگەل باخڤە و هاریکاریا وی بکە هێدی هەناسێ بدەت؛ هەناسەدان د ناڤ کیسکێ کاغەزی دا ئێدی ناهێتە پێشنیارکرن","برینا سەری: ئەگەر گومانا برینا ستوونا پشتێ هەبوو نەلڤینە، مەگەر جه مەترسیدار بیت یان پێدڤی ب CPR هەبیت (هنگێ سەر، ستۆ و پشتێ ل سەر ئێک هێلێ بهێلە)، و ل سەر تەنشتێ (Recovery Position) دانەنە؛ چاڤدێریا هشیاری و هەناسێ بکە و گازی ١٢٢ بکە","شکەستن (Fracture): ئەندامی وەکی خوە جیگیر بکە (Splint)، ڕاست نەکە، سەهۆلا د قوماشی دا پێچای بۆ ئێشێ دانە و گازی ١٢٢ بکە","شۆکا کارەبایێ: کارەبایێ ببڕە، ئەگەر هەناسە نەدا CPR بکە؛ هەمی دڤێت ل نەخۆشخانێ پشکنینا دلی (ECG) بکەن","ژەهربوون: ١) کیژ ماددە؟ ٢) چەند؟ ٣) کەنگی؟ — گازی ١٢٢ بکە، قوتیا ماددێ ب خوە ڤە ببە، و وی نەدە ڤەڕشاندن","پێڤەدانا مارێ (Snake Bite): کەسی ئارام و بێ لڤین بهێلە و ئەندامی ب داری جیگیر بکە؛ چ نەبەستە، نەبڕە و خوینێ نەمژە؛ ئێکسەر گازی ١٢٢ بکە"]}],media:[{kind:"video",src:"media/videos/gov_cpr_workplace.mp4",title:"CPR ل فەرمانگەهێ (Workplace CPR)",description:"CPR ل جهێ کاری"},{kind:"video",src:"media/videos/gov_aed_demo.mp4",title:"نیشاندانا AED (AED Demo)",description:"بکارئینانا AED"}],quiz:[{question:"ئێکەم هەنگاڤ د پشکنینا ئێکێ دا چییە؟",options:[{text:"ئێکسەر CPR",correct:!1},{text:"پشکنینا مەترسیێ (Danger)",correct:!0},{text:"گازی ١٢٢ بکە",correct:!1},{text:"AED",correct:!1}],explanation:"بەری هەر تشتەکی پشتڕاست ببە کو جهـ بۆ تە سەلامەتە — ئەگەر تو بریندار ببی، نەشێی هاریکاریێ بکەی."},{question:"د CPR دا، کویراهیا فشاران بۆ مەزنان چەندە؟",options:[{text:"٢-٣ سم",correct:!1},{text:"٥-٦ سم",correct:!0},{text:"٨-١٠ سم",correct:!1},{text:"چ ژ ڤان نە",correct:!1}],explanation:"٥-٦ سم بۆ هەمی مەزنان (AHA 2025)."},{question:"ئەگەر شۆکا AED د ٣-٥ خولەکێن ئێکێ دا پشتی کەفتنێ بهێتە دان، شانسا ڕزگاربوونێ دشێت بگەهیتە چەند؟",options:[{text:"١٠٪",correct:!1},{text:"هەتا ٥٠-٧٠٪",correct:!0},{text:"٢٠٪",correct:!1},{text:"١٠٠٪",correct:!1}],explanation:"شۆکا زوو د ٣-٥ خولەک دا دشێت ڕێژا ڕزگاربوونێ بگەهینیتە ٥٠-٧٠٪؛ هەر خولەکەکا گیرۆبوونێ شانسێ ب ڕێژەیەکا بەرچاڤ کێم دکەت."},{question:"بۆ زارۆکەکێ ژ ١ سالی کێمتر کو خەندقیایە (و هشیارە)، چ دهێتە کرن؟",options:[{text:"ئێکسەر فشارێن زکی (Heimlich)",correct:!1},{text:"٥ لێدانێن پشتێ + ٥ فشارێن سنگی",correct:!0},{text:"تەنێ بهێلە",correct:!1},{text:"ئێکسەر CPR",correct:!1}],explanation:"٥ لێدانێن پشتێ و ٥ فشارێن سنگی ب بنێ ئێک دەستی — چ جاران فشارێن زکی بۆ ساوایان نە (AHA 2025)."},{question:"پشتی دانانا تۆرنیکێتێ، چ دڤێت بکەی؟",options:[{text:"هەر ٦ دەمژمێران سست بکە",correct:!1},{text:"دەمێ دانانێ بنڤیسە و چ جاران سست نەکە",correct:!0},{text:"پشتی ١٠ خولەک لابە",correct:!1},{text:"هەر ٢٠ خولەک سست بکە دا خوین بگەهیتێ",correct:!1}],explanation:"دەمێ دانانێ بنڤیسە (Stop the Bleed). تۆرنیکێت ل جهێ خوە دمینیت هەتا تیمێ پزیشکی لادبەت؛ سستکرن خوینبەربوونێ دزڤڕینیت."},{question:"سووتن دڤێت ٢٠ خولەک ب چ ئاڤێ بهێتە سارکرن؟",options:[{text:"ئاڤا گەرم",correct:!1},{text:"ئاڤا فێنک یا ڕەوان، نە سەهۆل",correct:!0},{text:"سەهۆل",correct:!1},{text:"دەرمان و مەرهەم",correct:!1}],explanation:"ئاڤا فێنک یا ڕەوان — نە ئاڤا گەرم (سووتنێ کویرتر دکەت) و نە سەهۆل (زیانێ دگەهینیتە پێستی)."}]},{id:20,code:"GOV-120",icon:"Siren",accent:"#2563eb",title:"کارێ بەرگرییا شارستانی و هەماهەنگی",subtitle:"CD Operations + ICS + Multi-Agency Response",summary:"ڕۆلا فەرمانگەهێ ل دەمێ بەرسڤدانا بەرگرییا شارستانی (١١٥) و هەماهەنگی دگەل لایەنێن دی",blocks:[{body:"فەرمانگەه دڤێت بزانن چەوا دگەل بەرگرییا شارستانی (١١٥) ل دەمێ تەنگاڤیان کار بکەن. ستانداردا NFPA 1660 (کو NFPA 1600 تێدا هاتیە کۆمکرن) و خولێن FEMA ICS-100/200 بنەمایێن نێڤدەولەتی نە. ل دویڤ ICS، ئێک فەرماندەرێ ڕویدانێ (Incident Commander) فەرمانێ ددەت، و هەمی تیمێن پزیشکی، پۆلیس، ئاگرکوژی و فەرمانگەه ل بن ڤێ فەرماندەییێ کار دکەن."},{heading:"١. سیستەمێ فەرماندەیا ڕویدانێ (ICS)",body:"ستانداردەکا ئێکگرتی بۆ هەمی لایەنان:",points:["خولێن ICS-100 و ICS-200 بۆ کارمەندێن سەرەکی پێدڤینە","فەرماندەرێ ڕویدانێ (IC): تەنێ ئێک، و بەرپرسیاریا گشتی یا ڕویدانێ ل سەر وی یە","پێنج بەش: فەرماندەیی (Command)، کار (Operations)، پلاندانان (Planning)، لۆجستیک (Logistics)، دارایی و کارگێڕی (Finance/Admin)","سنوورێ سەرپەرشتیێ (Span of Control): ٣-٧ کەس بۆ هەر سەرپەرشتیارەکی (باشترین ٥)","هەر ڕویدانەک ناڤەکێ تایبەت وەردگریت (دیرۆک + جهـ + جۆر)","زمانێ ساددە (Plain Language): کۆد و کورتکرنێن تایبەت بکارنەئینە","پلانا کارێ ڕویدانێ (IAP) بۆ هەر ماوەیەکا کاری (Operational Period)، کو ب گشتی ١٢ یان ٢٤ دەمژمێرن","ئەگەر چەند لایەن بەرپرس بن: فەرماندەیا ئێکگرتی (Unified Command) — فەرماندەرێن لایەنان پێکڤە ئێک پلانێ دادنێن"]},{heading:"٢. پەیوەندیکرن ب ١١٥ — چ بێژی",body:"ئارام بە، ب ڕوونی باخڤە و ڤان تشتان ب ڤی ڕێزبەندیێ بێژە:",points:["١. بەری هەمی تشتان جهێ دروست: ئاڤاهی و ناڤێ فەرمانگەهێ، جادە، نیشانەکا دیار ل نێزیک و نهۆم","٢. چ چێبوو: ئاگر، تەقین، ڕویدان، ژەهربوون","٣. چەند کەس بریندار یان گیر بووینە","٤. هەر مەترسیەک: بەلاڤبوونا ئاگری، غاز، کارەبا، ماددێن کیمیایی","٥. ناڤێ خوە و ژمارا تەلەفۆنا خوە","٦. بەرسڤا پرسیاران بدە، ڕێنماییان پەیڕەو بکە و تەلەفۆنێ دانەخە هەتا ئەو نەبێژن"]},{heading:"٣. بەرسڤدانا چەند لایەنان (Multi-Agency Response)",body:"دەمێ چەند لایەن دگەهن:",points:["١١٥ بەرگرییا شارستانی: ڤەمراندنا ئاگری، ڕزگارکرن، ماددێن مەترسیدار (HazMat)","١٢٢ ئەمبوولانس: چارەسەریا پزیشکی و ڤەگوهاستن","١٠٤ پۆلیس: گرتنا دەوروبەری و ڕێکخستنا هاتوچۆیێ","دائیرا کارەبایێ: بڕینا کارەبایێ","دائیرێن ئاڤ و غازێ: بڕینا ئاڤ و غازێ ئەگەر دەرکەفتن هەبیت","وەزارەتا ساخلەمیێ: ئامادەکرنا نەخۆشخانەیان","دەستەیا ژینگەهێ: ڕژانا ماددێن کیمیایی","ناڤەندا کارێن تەنگاڤیێ (EOC — Emergency Operations Center) بۆ ڕویدانێن مەزن"]},{heading:"٤. ڕۆلا فەرمانگەهێ ل دەمێ تەنگاڤیێ",body:"چ دڤێت تو بکەی هەتا ١١٥ دگەهیت:",points:["١. گازی ١١٥ بکە (و ١٢٢ ئەگەر بریندار هەبن) و جهی بەری هەمی تشتان بێژە","٢. ئاگەهدارکرنا ناڤخوەیی چالاک بکە (زەنگا ئاگری یان بلندگۆ)","٣. کارمەند ل خالا کۆمبوونێ — ژمارتنا کەسان (Accountability)","٤. نەخشەیا ئاڤاهیێ ئامادە بکە: مەترسی و کێلۆنێن کارەبا، غاز و ئاڤێ","٥. ئەفسەرێ پەیوەندیێ (Liaison Officer): تەنێ ئێک کەس پەیوەندیێ دگەل ١١٥ دکەت","٦. پەڕێن SDS و لیستێن پەیوەندیێ ئامادە بکە","٧. ڕێکخستنا هاتوچۆیێ: ڕێکێ بۆ ترومبێلێن تەنگاڤیێ ڤەکری بهێلە","٨. بەرپرسێ زانیاریێن گشتی (PIO): زانیاریدان بۆ خەلکی و میدیا ب ڕێکخستی","٩. تۆمارکرن: وێنە، ڤیدیۆ و گۆتنێن شاهدان","١٠. ڕادەستکرنا فەرماندەییێ: دەمێ ١١٥ دگەهیت، فەرماندەیی بۆ فەرماندەرێ ١١٥ دهێتە ڕادەستکرن"]},{heading:"٥. تیمێ بەرسڤدانا تەنگاڤیێ ل فەرمانگەهێ (ERT)",body:"پێکهاتا پێشنیارکری:",points:["فەرماندەرێ ڕویدانێ (IC): ڕێڤەبەر یان جێگرێ ڕێڤەبەری","هەماهەنگکەرێ ئاگەهدارکرنێ: دوگمەیا ئاگری و پەیوەندی","بەرپرسێن قاتان (Floor Wardens): ٢ ل هەر قاتەکی، بۆ ڕێکێن دەرکەفتنێ","تیمێ هەوارهاتنا ئێکێ: ٢-٣ کارمەندێن ڕاهێنانکری ل سەر CPR و AED","تیمێ گەڕیانێ: پشکنینا ژووران و پشتڕاستکرنا چۆلکرنا ئاڤاهیێ","تیمێ تەمرینکان: کارمەندێن ڕاهێنانکری بۆ ڤەمراندنا ئاگرێن بچووک ل قۆناغا دەستپێکێ","پەیوەندی: تەلەفۆن دگەل ١١٥ و هەماهەنگیا ناڤخوەیی","ڕاهێنان: ڕاهێنانا دەستپێکێ و نووکرنا سالانە"]},{heading:"٦. ڕاهێنان و تاقیکرن (Drills + Tabletop Exercises)",body:"جۆرێن ڕاهێنانێ (FEMA HSEEP):",points:["ڕاهێنانا دەرکەفتنێ (Drill): ل دویڤ ڤێ بەرنامەیێ، هەر ٣ هەیڤان جارەکێ","ڕاهێنانا ل سەر مێزێ (Tabletop Exercise): ڕێڤەبەر و بەرپرس ل دۆر مێزێ سیناریۆیەکێ گەنگەشە دکەن","ڕاهێنانا کاری (Functional Exercise): تەنێ تیم و ئەرکێن سەرەکی (پەیوەندی، فەرماندەیی) دهێنە تاقیکرن","ڕاهێنانا تەمام (Full-Scale): هەمی ئاڤاهی و لایەنێن دەرڤە، لایێ کێم ئێک جار ل سالێ","ڕاپۆرتا پشتی ڕاهێنانێ (After-Action Report) ب زوویی بنڤیسە","ئارمانج: دیارکرنا چ باش بوو، چ کێم بوو و چ دڤێت بهێتە گوهۆڕین","باشترکرنا بەردەوام: ئەنجامێن AAR بکە د ناڤ ڕێکارێن کاری (SOP) دا"]},{heading:"٧. پلانا پەیوەندیێ (Communication Plan)",body:"بێ پەیوەندی، چ کار ب ڕێکێ ناچیت:",points:["سەرەکی: تەلەفۆنێن فەرمانگەهێ و سیستەمێ بلندگۆیێ (PA)","دووێ: مۆبایل و ڕادیۆیا دوو-ئالی","سێیێ: هنارتنا کەسان ب پێیان (Runners)","جهگر: تەلەفۆنا سەتەلایتی بۆ ڕویدانێن مەزن","تاقیکرن: هەر حەفتی بۆ تیمێن سەرەکی","لیستا تەلەفۆنان: ٢٤/٧ ئامادە و نووکری بیت","بۆ خەلکی: هێلا تەلەفۆنێ، مالپەر و تۆڕێن جڤاکی — تەنێ ب ڕێکا PIO","تێبینی: ل ڕویدانێن مەزن تۆڕا مۆبایلێ دبیت قەرەبالغ ببیت — نامێن SMS ب گشتی باشتر دگەهن"]},{heading:"٨. هەلسەنگاندنا پشتی ڕویدانێ (After-Action Review)",body:"پشکنینا پشتی ڕویدانێ:",points:["پێشنیار: د ماوەیێ ٧٢ دەمژمێران دا پشتی هەر ڕویدانەکێ، دەمێ بیرهاتن هێشتا نوو","بەشداربوونا هەمی لایەنان: IC، کار، لۆجستیک و لایەنێن دەرڤە","٤ پرسیار: چ هاتبوو پلاندانان؟ چ چێبوو؟ بۆچی جوداهی هەبوو؟ جارا بهێت دێ چ گوهۆڕین؟","پیڤەر: دەمێ بەرسڤدانێ، ژمارا برینداران، زیانێن مالی","تۆمارکرن: ڕاپۆرتا وانێن وەرگرتی (Lessons Learned)","نووکرن: SOP، پلانا تەنگاڤیێ (EOP) و کەرەستێن ڕاهێنانێ","دویڤچوون: پشتی ٣٠، ٦٠ و ٩٠ ڕۆژان جێبەجێکرنێ بپشکنە","پارڤەکرن: ئەنجامان دگەل لایەنێن دی پارڤە بکە"]}],media:[{kind:"video",src:"media/videos/gov_ics_demo.mp4",title:"ICS ل کاری دا (ICS in Action)",description:"ICS ل کارەساتەکا ڕاستەقینە"},{kind:"image",src:"media/images/gov_salute_card.png",title:"کارتا پەیوەندیکرنا ١١٥",description:"کارتا بیرئینانێ: چ بێژی دەمێ گازی ١١٥ دکەی"}],quiz:[{question:"د ICS دا، چەند فەرماندەرێن ڕویدانێ (IC) پێدڤینە؟",options:[{text:"٣-٥",correct:!1},{text:"تەنێ ئێک",correct:!0},{text:"هەر کارمەندەک",correct:!1},{text:"٢-٤",correct:!1}],explanation:"د ICS دا ئێک فەرماندەرێ ڕویدانێ هەیە. ئەگەر چەند لایەن بەرپرس بن، فەرماندەیا ئێکگرتی (Unified Command) ب ئێک پلانا هەڤپشک کار دکەت."},{question:"دەمێ گازی ١١٥ دکەی، پێشی چ دبێژی؟",options:[{text:"ناڤێ خوە و ڕۆلا خوە",correct:!1},{text:"جهێ دروست: ئاڤاهی، جادە، نیشانەکا دیار ل نێزیک و نهۆم",correct:!0},{text:"کەنگی ڕویدان دەستپێکر",correct:!1},{text:"چ کەرەستە ل نک تە هەنە",correct:!1}],explanation:"بەری هەمی تشتان جهێ دروست بێژە. پاشان بێژە چ چێبوو، چەند کەس بریندار یان گیر بووینە، هەر مەترسیەک، و ناڤ و ژمارا تەلەفۆنا خوە."},{question:"دەمێ ١١٥ دگەهیت، فەرماندەیی دکەڤیتە دەستێ کێ؟",options:[{text:"ERT بەردەوام دبیت",correct:!1},{text:"فەرماندەرێ ١١٥",correct:!0},{text:"ئەفسەرێ پەیوەندیێ (Liaison)",correct:!1},{text:"پۆلیس",correct:!1}],explanation:"ڕادەستکرنا فەرماندەییێ: دەمێ ١١٥ دگەهیت، فەرماندەیی بۆ فەرماندەرێ ١١٥ دهێتە ڕادەستکرن و ERT هاریکاریا وی دکەت."},{question:"ڕاهێنانا ل سەر مێزێ (Tabletop Exercise) چییە؟",options:[{text:"ڕاهێنانا دەرکەفتنا هەمی ئاڤاهیێ",correct:!1},{text:"گەنگەشەکرنا سیناریۆیەکێ ل دۆر مێزێ دگەل بەرپرسان",correct:!0},{text:"تاقیکرنا سیرێنێ",correct:!1},{text:"ڕاهێنانا بکارئینانا تەمرینکان",correct:!1}],explanation:"ڕاهێنانا ل سەر مێزێ گەنگەشەکرنا سیناریۆیەکێ یە بێ لڤاندنا کەس و کەرەستەیان، دا پلان و ئەرک بهێنە تاقیکرن (FEMA HSEEP)."},{question:"پێشنیار دهێتە کرن هەلسەنگاندنا پشتی ڕویدانێ (AAR) د ماوەیێ چەند دەمژمێران دا بهێتە کرن؟",options:[{text:"٢٤",correct:!1},{text:"٤٨",correct:!1},{text:"٧٢",correct:!0},{text:"١٦٨",correct:!1}],explanation:"د ماوەیێ ٧٢ دەمژمێران دا — دەمێ بیرهاتن هێشتا نوو و تەمام."},{question:"سنوورێ سەرپەرشتیێ (Span of Control) د ICS دا چەندە؟",options:[{text:"٢ کەس",correct:!1},{text:"٣-٧ کەس",correct:!0},{text:"١٠+ کەس",correct:!1},{text:"بێ سنوور",correct:!1}],explanation:"ل دویڤ NIMS: ٣-٧ کەس بۆ هەر سەرپەرشتیارەکی، و ٥ باشترینە."}]}],t={lessons:e};export{t as default,e as lessons};
